'use strict';

const crypto = require('node:crypto');
const { spawnSync } = require('node:child_process');
const path = require('node:path');

const V = require('./vnext-contract');
const RequirementRegistry = require('./requirement-registry');
const { normalizeScopeCandidate } = require('./scope-path');
const { extractSpecifiers, resolveSpecifier } = require('./plan-impact');

const CANDIDATE_SCHEMA = 'kodjo.vnext.impact-candidates.v1';
const DIRECT_SCAN_SCHEMA = 'kodjo.vnext.direct-import-scan.v1';
const IMPACT_SCHEMA = 'kodjo.vnext.impact-graph.v1';

const CHANGE_KINDS = Object.freeze(['MODIFY', 'CREATE', 'DELETE', 'NO_CHANGE']);
const EXISTING_CHANGE_KINDS = Object.freeze(['MODIFY', 'DELETE', 'NO_CHANGE']);
const CREATE_CHANGE_KINDS = Object.freeze(['CREATE', 'NO_CHANGE']);
const CREATE_ROOTS = Object.freeze(['app/', 'src/', 'tests/', 'assets/', 'docs/', 'scripts/', '.github/']);
const SOURCE_EXTENSIONS = Object.freeze(['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs']);

function git(args, cwd, encoding = 'utf8') {
  const result = spawnSync('git', args, {
    cwd,
    encoding,
    windowsHide: true,
    shell: false,
    maxBuffer: 64 * 1024 * 1024,
  });
  if (result.error || result.status !== 0) {
    V.fail(
      'VNEXT_IMPACT_GIT_FAILED',
      `git ${args.join(' ')}: ${String(result.stderr || result.error?.message || '').trim()}`,
    );
  }
  return result.stdout;
}

function normalizeRepoPath(value, code = 'VNEXT_IMPACT_PATH_INVALID', label = 'path') {
  const normalized = normalizeScopeCandidate(value);
  if (!normalized || normalized !== value) V.fail(code, `${label}=${String(value)}`);
  V.assertUnicodeExactText(normalized, code, label);
  return normalized;
}

function candidateKind(file) {
  if (/(?:^|\/)(?:__tests__|tests?)\//.test(file) || /\.(?:test|spec)\.[^.]+$/.test(file)) return 'TEST';
  if (file.startsWith('.github/')) return 'WORKFLOW';
  if (file.startsWith('docs/') || file.endsWith('.md')) return 'DOCUMENTATION';
  if (file.startsWith('assets/')) return 'ASSET';
  if (SOURCE_EXTENSIONS.some((ext) => file.endsWith(ext)) || /\.(?:json|ya?ml|ps1|py|sh)$/.test(file)) return 'CODE';
  return 'OTHER';
}

function validateCreateSlot(slot, revision, existingFiles, index) {
  V.assertExactKeys(
    slot,
    ['path', 'policy_id', 'policy_hash'],
    [],
    'VNEXT_CREATE_SLOT_KEYS_INVALID',
  );
  const repoPath = normalizeRepoPath(slot.path, 'VNEXT_CREATE_SLOT_PATH_INVALID', `create_slots[${index}].path`);
  if (!CREATE_ROOTS.some((root) => repoPath.startsWith(root))) {
    V.fail('VNEXT_CREATE_SLOT_ROOT_FORBIDDEN', repoPath);
  }
  if (existingFiles.has(repoPath)) V.fail('VNEXT_CREATE_SLOT_ALREADY_EXISTS', repoPath);
  V.assertNonEmptyString(slot.policy_id, 'VNEXT_CREATE_SLOT_POLICY_INVALID', 'policy_id');
  V.assertSha64(slot.policy_hash, 'VNEXT_CREATE_SLOT_POLICY_HASH_INVALID', 'policy_hash');
  return Object.freeze({
    candidate_id: V.stableId('CAND', [revision, 'CREATE_SLOT', repoPath, slot.policy_id, slot.policy_hash]),
    path: repoPath,
    candidate_kind: 'CREATE_SLOT',
    origin: 'CREATE_SLOT_POLICY',
    policy_id: slot.policy_id,
    policy_hash: slot.policy_hash,
    allowed_change_kinds: [...CREATE_CHANGE_KINDS],
  });
}

function buildCandidateManifest({ cwd = process.cwd(), revision, createSlots = [] }) {
  V.assertSha40(revision, 'VNEXT_IMPACT_REVISION_INVALID', 'revision');
  git(['cat-file', '-e', revision + '^{commit}'], cwd);

  const rawTree = git(['ls-tree', '-r', '-z', revision], cwd, 'buffer');
  const treeSha256 = crypto.createHash('sha256').update(rawTree).digest('hex');
  const rawNames = git(['ls-tree', '-r', '--name-only', '-z', revision], cwd, 'buffer');
  const files = rawNames.toString('utf8').split('\0').filter(Boolean)
    .map((file) => normalizeRepoPath(file))
    .sort();

  const fileSet = new Set(files);
  const candidates = files.map((file) => Object.freeze({
    candidate_id: V.stableId('CAND', [revision, 'EXISTING_FILE', file]),
    path: file,
    candidate_kind: candidateKind(file),
    origin: 'GIT_TREE',
    policy_id: null,
    policy_hash: null,
    allowed_change_kinds: [...EXISTING_CHANGE_KINDS],
  }));

  if (!Array.isArray(createSlots)) V.fail('VNEXT_CREATE_SLOTS_INVALID');
  for (let index = 0; index < createSlots.length; index += 1) {
    candidates.push(validateCreateSlot(createSlots[index], revision, fileSet, index));
  }

  candidates.sort((a, b) => a.path.localeCompare(b.path) || a.origin.localeCompare(b.origin));
  const ids = candidates.map((candidate) => candidate.candidate_id);
  if (new Set(ids).size !== ids.length) V.fail('VNEXT_IMPACT_CANDIDATE_ID_DUPLICATE');
  const pathOrigin = candidates.map((candidate) => `${candidate.origin}\u0000${candidate.path}`);
  if (new Set(pathOrigin).size !== pathOrigin.length) V.fail('VNEXT_IMPACT_CANDIDATE_DUPLICATE');

  return V.sealContract({
    schema_version: CANDIDATE_SCHEMA,
    revision,
    git_tree_sha256: treeSha256,
    candidate_count: candidates.length,
    candidates,
  });
}

function validateCandidateManifest(manifest) {
  V.assertExactKeys(
    manifest,
    ['schema_version', 'revision', 'git_tree_sha256', 'candidate_count', 'candidates', 'contract_hash'],
    [],
    'VNEXT_IMPACT_CANDIDATE_MANIFEST_KEYS_INVALID',
  );
  if (manifest.schema_version !== CANDIDATE_SCHEMA) {
    V.fail('VNEXT_IMPACT_CANDIDATE_SCHEMA_INVALID', manifest.schema_version);
  }
  V.assertSha40(manifest.revision, 'VNEXT_IMPACT_REVISION_INVALID', 'revision');
  V.assertSha64(manifest.git_tree_sha256, 'VNEXT_IMPACT_TREE_HASH_INVALID', 'git_tree_sha256');
  V.verifyContractHash(manifest, 'VNEXT_IMPACT_CANDIDATE_HASH_MISMATCH');
  if (!Array.isArray(manifest.candidates) || manifest.candidate_count !== manifest.candidates.length) {
    V.fail('VNEXT_IMPACT_CANDIDATE_COUNT_MISMATCH');
  }
  const ids = new Set();
  for (const candidate of manifest.candidates) {
    V.assertExactKeys(
      candidate,
      [
        'candidate_id', 'path', 'candidate_kind', 'origin', 'policy_id', 'policy_hash',
        'allowed_change_kinds',
      ],
      [],
      'VNEXT_IMPACT_CANDIDATE_KEYS_INVALID',
    );
    normalizeRepoPath(candidate.path);
    if (ids.has(candidate.candidate_id)) V.fail('VNEXT_IMPACT_CANDIDATE_ID_DUPLICATE', candidate.candidate_id);
    ids.add(candidate.candidate_id);
    const expectedId = candidate.origin === 'GIT_TREE'
      ? V.stableId('CAND', [manifest.revision, 'EXISTING_FILE', candidate.path])
      : V.stableId('CAND', [
        manifest.revision, 'CREATE_SLOT', candidate.path, candidate.policy_id, candidate.policy_hash,
      ]);
    if (candidate.candidate_id !== expectedId) V.fail('VNEXT_IMPACT_CANDIDATE_ID_MISMATCH', candidate.candidate_id);
    if (candidate.origin === 'GIT_TREE') {
      if (candidate.candidate_kind !== candidateKind(candidate.path)) {
        V.fail('VNEXT_IMPACT_CANDIDATE_KIND_MISMATCH', candidate.path);
      }
      if (candidate.policy_id !== null || candidate.policy_hash !== null) V.fail('VNEXT_IMPACT_GIT_CANDIDATE_POLICY_FORBIDDEN');
      if (V.canonicalStringify(candidate.allowed_change_kinds) !== V.canonicalStringify(EXISTING_CHANGE_KINDS)) {
        V.fail('VNEXT_IMPACT_EXISTING_CHANGE_KINDS_INVALID', candidate.path);
      }
    } else if (candidate.origin === 'CREATE_SLOT_POLICY') {
      if (candidate.candidate_kind !== 'CREATE_SLOT') V.fail('VNEXT_IMPACT_CREATE_SLOT_KIND_INVALID', candidate.path);
      if (!CREATE_ROOTS.some((root) => candidate.path.startsWith(root))) {
        V.fail('VNEXT_CREATE_SLOT_ROOT_FORBIDDEN', candidate.path);
      }
      V.assertNonEmptyString(candidate.policy_id, 'VNEXT_CREATE_SLOT_POLICY_INVALID', 'policy_id');
      V.assertSha64(candidate.policy_hash, 'VNEXT_CREATE_SLOT_POLICY_HASH_INVALID', 'policy_hash');
      if (V.canonicalStringify(candidate.allowed_change_kinds) !== V.canonicalStringify(CREATE_CHANGE_KINDS)) {
        V.fail('VNEXT_IMPACT_CREATE_CHANGE_KINDS_INVALID', candidate.path);
      }
    } else {
      V.fail('VNEXT_IMPACT_CANDIDATE_ORIGIN_INVALID', candidate.origin);
    }
  }
  return true;
}

function verifyCandidateManifestAtHead(manifest, { cwd = process.cwd() } = {}) {
  validateCandidateManifest(manifest);
  git(['cat-file', '-e', manifest.revision + '^{commit}'], cwd);
  const rawTree = git(['ls-tree', '-r', '-z', manifest.revision], cwd, 'buffer');
  const currentHash = crypto.createHash('sha256').update(rawTree).digest('hex');
  if (currentHash !== manifest.git_tree_sha256) V.fail('VNEXT_IMPACT_TREE_DRIFT');
  const tracked = new Set(
    git(['ls-tree', '-r', '--name-only', '-z', manifest.revision], cwd, 'buffer')
      .toString('utf8').split('\0').filter(Boolean).map((file) => normalizeRepoPath(file)),
  );
  for (const candidate of manifest.candidates) {
    if (candidate.origin === 'GIT_TREE' && !tracked.has(candidate.path)) {
      V.fail('VNEXT_IMPACT_EXISTING_PATH_ABSENT', candidate.path);
    }
    if (candidate.origin === 'CREATE_SLOT_POLICY' && tracked.has(candidate.path)) {
      V.fail('VNEXT_CREATE_SLOT_ALREADY_EXISTS', candidate.path);
    }
  }
  return true;
}

function scanOneLevelDirectImporters({
  cwd = process.cwd(),
  candidateManifest,
  modifyCandidateIds,
}) {
  validateCandidateManifest(candidateManifest);
  if (!Array.isArray(modifyCandidateIds) || modifyCandidateIds.length === 0) {
    V.fail('VNEXT_DIRECT_IMPORT_TARGETS_EMPTY');
  }
  if (new Set(modifyCandidateIds).size !== modifyCandidateIds.length) {
    V.fail('VNEXT_DIRECT_IMPORT_TARGET_DUPLICATE');
  }

  const byId = new Map(candidateManifest.candidates.map((candidate) => [candidate.candidate_id, candidate]));
  const targets = modifyCandidateIds.map((id) => {
    const candidate = byId.get(id);
    if (!candidate) V.fail('VNEXT_DIRECT_IMPORT_TARGET_UNKNOWN', id);
    if (candidate.origin !== 'GIT_TREE') V.fail('VNEXT_DIRECT_IMPORT_TARGET_NOT_EXISTING', id);
    if (!SOURCE_EXTENSIONS.some((ext) => candidate.path.endsWith(ext))) {
      V.fail('VNEXT_DIRECT_IMPORT_TARGET_NOT_SOURCE', candidate.path);
    }
    return candidate;
  });
  const targetPathSet = new Set(targets.map((target) => target.path));
  const fileSet = new Set(
    candidateManifest.candidates
      .filter((candidate) => candidate.origin === 'GIT_TREE')
      .map((candidate) => candidate.path),
  );
  const idByPath = new Map(
    candidateManifest.candidates
      .filter((candidate) => candidate.origin === 'GIT_TREE')
      .map((candidate) => [candidate.path, candidate.candidate_id]),
  );

  const importers = [];
  const sourceFiles = [...fileSet]
    .filter((file) => SOURCE_EXTENSIONS.some((ext) => file.endsWith(ext)))
    .sort();

  for (const file of sourceFiles) {
    if (targetPathSet.has(file)) continue;
    const source = String(git(['show', candidateManifest.revision + ':' + file], cwd));
    const triggeredPaths = extractSpecifiers(source)
      .map((specifier) => resolveSpecifier(file, specifier, fileSet))
      .filter((resolved) => resolved && targetPathSet.has(resolved));
    const uniquePaths = [...new Set(triggeredPaths)].sort();
    if (uniquePaths.length === 0) continue;

    importers.push({
      candidate_id: idByPath.get(file),
      path: file,
      candidate_kind: candidateKind(file),
      triggered_by_candidate_ids: uniquePaths.map((targetPath) => idByPath.get(targetPath)).sort(),
    });
  }

  importers.sort((a, b) => a.path.localeCompare(b.path));
  return V.sealContract({
    schema_version: DIRECT_SCAN_SCHEMA,
    revision: candidateManifest.revision,
    candidate_manifest_hash: candidateManifest.contract_hash,
    target_candidate_ids: [...modifyCandidateIds].sort(),
    importer_count: importers.length,
    importers,
  });
}

function validateDirectImportScan(scan, candidateManifest) {
  V.assertExactKeys(
    scan,
    [
      'schema_version', 'revision', 'candidate_manifest_hash', 'target_candidate_ids',
      'importer_count', 'importers', 'contract_hash',
    ],
    [],
    'VNEXT_DIRECT_IMPORT_SCAN_KEYS_INVALID',
  );
  if (scan.schema_version !== DIRECT_SCAN_SCHEMA) V.fail('VNEXT_DIRECT_IMPORT_SCAN_SCHEMA_INVALID');
  V.verifyContractHash(scan, 'VNEXT_DIRECT_IMPORT_SCAN_HASH_MISMATCH');
  validateCandidateManifest(candidateManifest);
  if (scan.revision !== candidateManifest.revision) V.fail('VNEXT_DIRECT_IMPORT_SCAN_REVISION_MISMATCH');
  if (scan.candidate_manifest_hash !== candidateManifest.contract_hash) {
    V.fail('VNEXT_DIRECT_IMPORT_CANDIDATE_MANIFEST_MISMATCH');
  }
  if (!Array.isArray(scan.importers) || scan.importer_count !== scan.importers.length) {
    V.fail('VNEXT_DIRECT_IMPORT_COUNT_MISMATCH');
  }
  return true;
}

function verifyDirectImportScanAtHead(scan, candidateManifest, { cwd = process.cwd() } = {}) {
  verifyCandidateManifestAtHead(candidateManifest, { cwd });
  validateDirectImportScan(scan, candidateManifest);
  const rebuilt = scanOneLevelDirectImporters({
    cwd, candidateManifest, modifyCandidateIds: scan.target_candidate_ids,
  });
  if (V.canonicalStringify(scan) !== V.canonicalStringify(rebuilt)) {
    V.fail('VNEXT_DIRECT_IMPORT_SCAN_REBUILD_MISMATCH');
  }
  return true;
}

function classificationKey(requirementId, candidateId) {
  return `${requirementId}\u0000${candidateId === null ? '<NO_TARGET>' : candidateId}`;
}

function normalizeClassification(row, index, requirementIds, candidateById) {
  V.assertExactKeys(
    row,
    [
      'requirement_id', 'candidate_id', 'change_kind', 'impact_reason',
      'dependency_evidence', 'tests_affected_candidate_ids', 'preservation_candidate_ids',
    ],
    [],
    'VNEXT_IMPACT_CLASSIFICATION_KEYS_INVALID',
  );
  if (!requirementIds.has(row.requirement_id)) V.fail('VNEXT_IMPACT_REQUIREMENT_UNKNOWN', row.requirement_id);
  if (!CHANGE_KINDS.includes(row.change_kind)) V.fail('VNEXT_IMPACT_CHANGE_KIND_INVALID', row.change_kind);
  V.assertUnicodeExactText(row.impact_reason, 'VNEXT_IMPACT_REASON_INVALID', `classifications[${index}].impact_reason`);
  const dependencyEvidence = V.uniqueStrings(
    row.dependency_evidence,
    'VNEXT_IMPACT_DEPENDENCY_EVIDENCE_INVALID',
    `classifications[${index}].dependency_evidence`,
    { allowEmpty: row.change_kind === 'NO_CHANGE' },
  );
  const testsAffected = V.uniqueStrings(
    row.tests_affected_candidate_ids,
    'VNEXT_IMPACT_TEST_IDS_INVALID',
    `classifications[${index}].tests_affected_candidate_ids`,
    { allowEmpty: true },
  );
  const preservation = V.uniqueStrings(
    row.preservation_candidate_ids,
    'VNEXT_IMPACT_PRESERVATION_IDS_INVALID',
    `classifications[${index}].preservation_candidate_ids`,
    { allowEmpty: true },
  );

  if (row.candidate_id === null) {
    if (row.change_kind !== 'NO_CHANGE') V.fail('VNEXT_IMPACT_NULL_TARGET_ONLY_NO_CHANGE');
    if (testsAffected.length || preservation.length) V.fail('VNEXT_IMPACT_NULL_TARGET_EDGES_FORBIDDEN');
  } else {
    V.assertNonEmptyString(row.candidate_id, 'VNEXT_IMPACT_CANDIDATE_ID_INVALID', 'candidate_id');
    const candidate = candidateById.get(row.candidate_id);
    if (!candidate) V.fail('VNEXT_IMPACT_CANDIDATE_UNKNOWN', row.candidate_id);
    if (!candidate.allowed_change_kinds.includes(row.change_kind)) {
      V.fail('VNEXT_IMPACT_CHANGE_KIND_NOT_ALLOWED', `${candidate.path}:${row.change_kind}`);
    }
  }

  for (const id of [...testsAffected, ...preservation]) {
    if (!candidateById.has(id)) V.fail('VNEXT_IMPACT_EDGE_CANDIDATE_UNKNOWN', id);
  }

  return {
    requirement_id: row.requirement_id,
    candidate_id: row.candidate_id,
    change_kind: row.change_kind,
    impact_reason: row.impact_reason,
    dependency_evidence: dependencyEvidence,
    tests_affected_candidate_ids: testsAffected,
    preservation_candidate_ids: preservation,
  };
}

function buildImpactGraph({
  requirementRegistry,
  candidateManifest,
  classifications,
  directImportScan = null,
}) {
  RequirementRegistry.assertReady(requirementRegistry);
  validateCandidateManifest(candidateManifest);
  if (!Array.isArray(classifications)) V.fail('VNEXT_IMPACT_CLASSIFICATIONS_INVALID');

  const requirementIds = new Set(requirementRegistry.requirements.map((req) => req.requirement_id));
  const candidateById = new Map(candidateManifest.candidates.map((candidate) => [candidate.candidate_id, candidate]));
  const normalized = classifications.map((row, index) =>
    normalizeClassification(row, index, requirementIds, candidateById));

  const seen = new Set();
  for (const row of normalized) {
    const key = classificationKey(row.requirement_id, row.candidate_id);
    if (seen.has(key)) V.fail('VNEXT_IMPACT_CLASSIFICATION_DUPLICATE', key);
    seen.add(key);
  }

  const rowsByRequirement = new Map();
  for (const reqId of requirementIds) rowsByRequirement.set(reqId, []);
  for (const row of normalized) rowsByRequirement.get(row.requirement_id).push(row);

  for (const [reqId, rows] of rowsByRequirement) {
    if (rows.length === 0) V.fail('VNEXT_IMPACT_REQUIREMENT_UNCOVERED', reqId);
    const targetlessNoChange = rows.filter((row) => row.candidate_id === null && row.change_kind === 'NO_CHANGE');
    if (targetlessNoChange.length > 1) V.fail('VNEXT_IMPACT_NO_CHANGE_DUPLICATE', reqId);
    if (targetlessNoChange.length === 1 && rows.length !== 1) {
      V.fail('VNEXT_IMPACT_NO_CHANGE_MIXED_WITH_TARGETS', reqId);
    }
  }

  const selectedModifyIds = [...new Set(
    normalized
      .filter((row) => row.change_kind === 'MODIFY' && row.candidate_id !== null)
      .map((row) => row.candidate_id),
  )].sort();
  const selectedDirectRootIds = selectedModifyIds.filter((id) => {
    const candidate = candidateById.get(id);
    return candidate
      && candidate.origin === 'GIT_TREE'
      && candidate.candidate_kind === 'CODE'
      && SOURCE_EXTENSIONS.some((ext) => candidate.path.endsWith(ext));
  });

  if (selectedDirectRootIds.length > 0) {
    if (!directImportScan) V.fail('VNEXT_DIRECT_IMPORT_SCAN_REQUIRED');
    validateDirectImportScan(directImportScan, candidateManifest);
    if (V.canonicalStringify(directImportScan.target_candidate_ids) !== V.canonicalStringify(selectedDirectRootIds)) {
      V.fail('VNEXT_DIRECT_IMPORT_TARGET_SET_MISMATCH');
    }

    const modifiedByRequirement = new Map();
    for (const row of normalized.filter((item) => item.change_kind === 'MODIFY')) {
      const set = modifiedByRequirement.get(row.requirement_id) || new Set();
      set.add(row.candidate_id);
      modifiedByRequirement.set(row.requirement_id, set);
    }

    for (const importer of directImportScan.importers) {
      for (const [reqId, targetIds] of modifiedByRequirement) {
        const relevant = importer.triggered_by_candidate_ids.some((id) => targetIds.has(id));
        if (!relevant) continue;
        const key = classificationKey(reqId, importer.candidate_id);
        if (!seen.has(key)) {
          V.fail('VNEXT_DIRECT_IMPORT_CLASSIFICATION_MISSING', `${reqId}:${importer.path}`);
        }
      }
    }
  } else if (directImportScan !== null) {
    V.fail('VNEXT_DIRECT_IMPORT_SCAN_UNEXPECTED');
  }

  const directByCandidate = new Map();
  if (directImportScan) {
    for (const importer of directImportScan.importers) {
      directByCandidate.set(importer.candidate_id, importer.triggered_by_candidate_ids);
    }
  }

  const impacts = normalized.map((row) => {
    const candidate = row.candidate_id === null ? null : candidateById.get(row.candidate_id);
    return {
      impact_id: V.stableId('IMP', [row.requirement_id, row.candidate_id, row.change_kind]),
      requirement_id: row.requirement_id,
      candidate_id: row.candidate_id,
      target_id: row.candidate_id,
      path: candidate ? candidate.path : null,
      target_kind: candidate ? candidate.candidate_kind : 'NO_TARGET',
      change_kind: row.change_kind,
      candidate_origin: candidate ? candidate.origin : 'REQUIREMENT_LEVEL',
      impact_reason: row.impact_reason,
      dependency_evidence: row.dependency_evidence,
      direct_import_trigger_ids: row.candidate_id && directByCandidate.has(row.candidate_id)
        ? [...directByCandidate.get(row.candidate_id)]
        : [],
      tests_affected_candidate_ids: row.tests_affected_candidate_ids,
      preservation_candidate_ids: row.preservation_candidate_ids,
    };
  }).sort((a, b) =>
    a.requirement_id.localeCompare(b.requirement_id)
      || String(a.path).localeCompare(String(b.path))
      || a.change_kind.localeCompare(b.change_kind));

  return V.sealContract({
    schema_version: IMPACT_SCHEMA,
    requirement_registry_hash: requirementRegistry.contract_hash,
    candidate_manifest_hash: candidateManifest.contract_hash,
    direct_import_scan_hash: directImportScan ? directImportScan.contract_hash : null,
    impact_count: impacts.length,
    requirement_count: requirementIds.size,
    impacts,
  });
}

function validateImpactGraph(graph, { requirementRegistry, candidateManifest, directImportScan = null }) {
  V.assertExactKeys(
    graph,
    [
      'schema_version', 'requirement_registry_hash', 'candidate_manifest_hash',
      'direct_import_scan_hash', 'impact_count', 'requirement_count', 'impacts', 'contract_hash',
    ],
    [],
    'VNEXT_IMPACT_GRAPH_KEYS_INVALID',
  );
  if (graph.schema_version !== IMPACT_SCHEMA) V.fail('VNEXT_IMPACT_GRAPH_SCHEMA_INVALID');
  V.verifyContractHash(graph, 'VNEXT_IMPACT_GRAPH_HASH_MISMATCH');
  if (graph.requirement_registry_hash !== requirementRegistry.contract_hash) {
    V.fail('VNEXT_IMPACT_REQUIREMENT_REGISTRY_HASH_MISMATCH');
  }
  if (graph.candidate_manifest_hash !== candidateManifest.contract_hash) {
    V.fail('VNEXT_IMPACT_CANDIDATE_MANIFEST_HASH_MISMATCH');
  }
  const expectedDirectHash = directImportScan ? directImportScan.contract_hash : null;
  if (graph.direct_import_scan_hash !== expectedDirectHash) V.fail('VNEXT_IMPACT_DIRECT_SCAN_HASH_MISMATCH');

  const classifications = graph.impacts.map((impact) => ({
    requirement_id: impact.requirement_id,
    candidate_id: impact.candidate_id,
    change_kind: impact.change_kind,
    impact_reason: impact.impact_reason,
    dependency_evidence: impact.dependency_evidence,
    tests_affected_candidate_ids: impact.tests_affected_candidate_ids,
    preservation_candidate_ids: impact.preservation_candidate_ids,
  }));
  const rebuilt = buildImpactGraph({
    requirementRegistry,
    candidateManifest,
    classifications,
    directImportScan,
  });
  if (V.canonicalStringify(rebuilt) !== V.canonicalStringify(graph)) {
    V.fail('VNEXT_IMPACT_GRAPH_REBUILD_MISMATCH');
  }
  return true;
}

module.exports = {
  verifyDirectImportScanAtHead,
  CANDIDATE_SCHEMA,
  DIRECT_SCAN_SCHEMA,
  IMPACT_SCHEMA,
  CHANGE_KINDS,
  CREATE_ROOTS,
  buildCandidateManifest,
  validateCandidateManifest,
  verifyCandidateManifestAtHead,
  scanOneLevelDirectImporters,
  validateDirectImportScan,
  buildImpactGraph,
  validateImpactGraph,
};

'use strict';

const V = require('./vnext-contract');
const RequirementRegistry = require('./requirement-registry');
const Impact = require('./impact-graph');

const SCHEMA = 'kodjo.vnext.plan-contract.v1';
const DISPOSITIONS = Object.freeze(['CHANGE', 'NO_CHANGE']);
const PROOF_TYPES = Object.freeze([
  'FUNCTIONAL_TEST',
  'STATIC_ANALYSIS',
  'VISUAL_COMPARE',
  'ACCESSIBILITY_CHECK',
  'DEVICE_CHECK',
]);
const TEST_ACTIONS = Object.freeze([
  'RUN_EXISTING',
  'ADAPT',
  'CREATE',
  'REMOVE',
  'NONE_WITH_JUSTIFICATION',
]);
const FORBIDDEN_POLICY = 'ALL_OUTSIDE_WRITE_SCOPE';

function isTestPath(value) {
  return typeof value === 'string'
    && (/(?:^|\/)(?:__tests__|tests?)\//.test(value) || /\.(?:test|spec)\.[^.]+$/.test(value));
}

function uniqueIds(values, code, label, { allowEmpty = false } = {}) {
  return V.uniqueStrings(values, code, label, { allowEmpty });
}

function impactIndex(impactGraph) {
  if (!impactGraph || !Array.isArray(impactGraph.impacts)) V.fail('VNEXT_PLAN_IMPACT_GRAPH_INVALID');
  const byId = new Map();
  const byRequirement = new Map();
  for (const impact of impactGraph.impacts) {
    if (byId.has(impact.impact_id)) V.fail('VNEXT_PLAN_IMPACT_ID_DUPLICATE', impact.impact_id);
    byId.set(impact.impact_id, impact);
    const list = byRequirement.get(impact.requirement_id) || [];
    list.push(impact);
    byRequirement.set(impact.requirement_id, list);
  }
  for (const list of byRequirement.values()) {
    list.sort((a, b) => a.impact_id.localeCompare(b.impact_id));
  }
  return { byId, byRequirement };
}

function candidateIndex(candidateManifest) {
  Impact.validateCandidateManifest(candidateManifest);
  return new Map(candidateManifest.candidates.map((candidate) => [candidate.candidate_id, candidate]));
}

function derivedTestAction(impact) {
  if (impact.change_kind === 'NO_CHANGE') return 'RUN_EXISTING';
  if (impact.change_kind === 'MODIFY') return 'ADAPT';
  if (impact.change_kind === 'CREATE') return 'CREATE';
  if (impact.change_kind === 'DELETE') return 'REMOVE';
  V.fail('VNEXT_PLAN_TEST_IMPACT_CHANGE_KIND_INVALID', impact.change_kind);
}

function normalizeImplementationIntents(rows, requirementId, changedImpacts) {
  if (!Array.isArray(rows)) V.fail('VNEXT_PLAN_IMPLEMENTATION_INTENTS_INVALID', requirementId);
  const changedById = new Map(changedImpacts.map((impact) => [impact.impact_id, impact]));
  const seen = new Set();
  const normalized = rows.map((row, index) => {
    V.assertExactKeys(row, ['impact_id', 'intent'], [], 'VNEXT_PLAN_IMPLEMENTATION_INTENT_KEYS_INVALID');
    const impact = changedById.get(row.impact_id);
    if (!impact) V.fail('VNEXT_PLAN_IMPLEMENTATION_INTENT_IMPACT_INVALID', row.impact_id);
    if (seen.has(row.impact_id)) V.fail('VNEXT_PLAN_IMPLEMENTATION_INTENT_DUPLICATE', row.impact_id);
    seen.add(row.impact_id);
    V.assertUnicodeExactText(
      row.intent,
      'VNEXT_PLAN_IMPLEMENTATION_INTENT_TEXT_INVALID',
      `implementation_intents[${index}].intent`,
    );
    return { impact_id: row.impact_id, intent: row.intent };
  });
  if (seen.size !== changedById.size) {
    const missing = [...changedById.keys()].filter((id) => !seen.has(id));
    V.fail('VNEXT_PLAN_IMPLEMENTATION_INTENT_MISSING', missing.join(','));
  }
  return normalized.sort((a, b) => a.impact_id.localeCompare(b.impact_id));
}

function normalizeTestObligations(rows, requirementId, requirementImpacts) {
  if (!Array.isArray(rows) || rows.length === 0) {
    V.fail('VNEXT_PLAN_TEST_OBLIGATIONS_EMPTY', requirementId);
  }
  const impactById = new Map(requirementImpacts.map((impact) => [impact.impact_id, impact]));
  const changedImpactIds = new Set(
    requirementImpacts
      .filter((impact) => ['MODIFY', 'CREATE', 'DELETE'].includes(impact.change_kind))
      .map((impact) => impact.impact_id),
  );
  const seenTargets = new Set();
  const normalized = rows.map((row, index) => {
    V.assertExactKeys(
      row,
      ['target_impact_id', 'covered_change_impact_ids', 'expected', 'justification'],
      [],
      'VNEXT_PLAN_TEST_OBLIGATION_KEYS_INVALID',
    );
    V.assertUnicodeExactText(
      row.expected,
      'VNEXT_PLAN_TEST_EXPECTED_INVALID',
      `test_obligations[${index}].expected`,
    );
    V.assertUnicodeExactText(
      row.justification,
      'VNEXT_PLAN_TEST_JUSTIFICATION_INVALID',
      `test_obligations[${index}].justification`,
    );

    const coveredChangeImpactIds = uniqueIds(
      row.covered_change_impact_ids,
      'VNEXT_PLAN_TEST_COVERAGE_INVALID',
      `test_obligations[${index}].covered_change_impact_ids`,
      { allowEmpty: changedImpactIds.size === 0 },
    ).sort();
    for (const impactId of coveredChangeImpactIds) {
      if (!changedImpactIds.has(impactId)) V.fail('VNEXT_PLAN_TEST_COVERAGE_IMPACT_INVALID', impactId);
    }

    if (row.target_impact_id === null) {
      const key = '<NONE>';
      if (seenTargets.has(key)) V.fail('VNEXT_PLAN_TEST_OBLIGATION_DUPLICATE', key);
      seenTargets.add(key);
      return {
        test_id: V.stableId('TEST', [requirementId, null, 'NONE_WITH_JUSTIFICATION', coveredChangeImpactIds]),
        target_impact_id: null,
        target_candidate_id: null,
        path: null,
        action: 'NONE_WITH_JUSTIFICATION',
        covered_change_impact_ids: coveredChangeImpactIds,
        expected: row.expected,
        justification: row.justification,
      };
    }

    V.assertNonEmptyString(
      row.target_impact_id,
      'VNEXT_PLAN_TEST_TARGET_INVALID',
      `test_obligations[${index}].target_impact_id`,
    );
    if (seenTargets.has(row.target_impact_id)) {
      V.fail('VNEXT_PLAN_TEST_OBLIGATION_DUPLICATE', row.target_impact_id);
    }
    seenTargets.add(row.target_impact_id);
    const impact = impactById.get(row.target_impact_id);
    if (!impact) V.fail('VNEXT_PLAN_TEST_IMPACT_UNKNOWN', row.target_impact_id);
    if (!isTestPath(impact.path)) V.fail('VNEXT_PLAN_TEST_TARGET_NOT_TEST', String(impact.path));
    const action = derivedTestAction(impact);
    return {
      test_id: V.stableId('TEST', [requirementId, impact.impact_id, action]),
      target_impact_id: impact.impact_id,
      target_candidate_id: impact.candidate_id,
      path: impact.path,
      action,
      covered_change_impact_ids: coveredChangeImpactIds,
      expected: row.expected,
      justification: row.justification,
    };
  });

  const targetIds = new Set(normalized.filter((row) => row.target_impact_id !== null).map((row) => row.target_impact_id));
  const coveredChanges = new Set(normalized.flatMap((row) => row.covered_change_impact_ids));
  const changedTests = requirementImpacts.filter((impact) =>
    isTestPath(impact.path) && ['MODIFY', 'CREATE', 'DELETE'].includes(impact.change_kind));
  for (const impact of changedTests) {
    if (!targetIds.has(impact.impact_id)) {
      V.fail('VNEXT_PLAN_CHANGED_TEST_UNBOUND', impact.impact_id);
    }
  }

  for (const impactId of changedImpactIds) {
    if (!coveredChanges.has(impactId)) V.fail('VNEXT_PLAN_CHANGE_WITHOUT_TEST_COVERAGE', impactId);
  }

  const affectedCandidateIds = new Set();
  for (const impact of requirementImpacts) {
    for (const candidateId of impact.tests_affected_candidate_ids || []) affectedCandidateIds.add(candidateId);
  }
  for (const candidateId of affectedCandidateIds) {
    const matching = requirementImpacts.filter((impact) => impact.candidate_id === candidateId && isTestPath(impact.path));
    if (matching.length === 0) V.fail('VNEXT_PLAN_AFFECTED_TEST_IMPACT_MISSING', candidateId);
    if (!matching.some((impact) => targetIds.has(impact.impact_id))) {
      V.fail('VNEXT_PLAN_AFFECTED_TEST_UNBOUND', candidateId);
    }
  }

  return normalized.sort((a, b) => a.test_id.localeCompare(b.test_id));
}

function normalizeProofObligations(rows, requirementId, tests) {
  if (!Array.isArray(rows) || rows.length === 0) V.fail('VNEXT_PLAN_PROOF_OBLIGATIONS_EMPTY', requirementId);
  const testByImpact = new Map(
    tests
      .filter((test) => test.target_impact_id !== null)
      .map((test) => [test.target_impact_id, test]),
  );
  const allChangedImpactIds = new Set(tests.flatMap((test) => test.covered_change_impact_ids));
  const normalized = [];
  const seen = new Set();

  rows.forEach((row, index) => {
    V.assertExactKeys(
      row,
      ['proof_type', 'target_test_impact_id', 'covered_change_impact_ids', 'expected', 'justification'],
      [],
      'VNEXT_PLAN_PROOF_OBLIGATION_KEYS_INVALID',
    );
    if (!PROOF_TYPES.includes(row.proof_type)) V.fail('VNEXT_PLAN_PROOF_TYPE_INVALID', row.proof_type);
    V.assertUnicodeExactText(
      row.expected,
      'VNEXT_PLAN_PROOF_EXPECTED_INVALID',
      `proof_obligations[${index}].expected`,
    );
    V.assertUnicodeExactText(
      row.justification,
      'VNEXT_PLAN_PROOF_JUSTIFICATION_INVALID',
      `proof_obligations[${index}].justification`,
    );

    const coveredChangeImpactIds = uniqueIds(
      row.covered_change_impact_ids,
      'VNEXT_PLAN_PROOF_COVERAGE_INVALID',
      `proof_obligations[${index}].covered_change_impact_ids`,
      { allowEmpty: allChangedImpactIds.size === 0 },
    ).sort();
    for (const impactId of coveredChangeImpactIds) {
      if (!allChangedImpactIds.has(impactId)) V.fail('VNEXT_PLAN_PROOF_COVERAGE_IMPACT_INVALID', impactId);
    }

    if (row.proof_type === 'FUNCTIONAL_TEST') {
      V.assertNonEmptyString(
        row.target_test_impact_id,
        'VNEXT_PLAN_FUNCTIONAL_PROOF_TARGET_REQUIRED',
        'target_test_impact_id',
      );
      const targetTest = testByImpact.get(row.target_test_impact_id);
      if (!targetTest) V.fail('VNEXT_PLAN_FUNCTIONAL_PROOF_TEST_UNKNOWN', row.target_test_impact_id);
      if (targetTest.action === 'REMOVE') V.fail('VNEXT_PLAN_FUNCTIONAL_PROOF_REMOVE_FORBIDDEN', row.target_test_impact_id);
      for (const impactId of coveredChangeImpactIds) {
        if (!targetTest.covered_change_impact_ids.includes(impactId)) {
          V.fail('VNEXT_PLAN_FUNCTIONAL_PROOF_COVERAGE_MISMATCH', impactId);
        }
      }
    } else if (row.target_test_impact_id !== null) {
      V.fail('VNEXT_PLAN_NON_TEST_PROOF_TARGET_FORBIDDEN', row.proof_type);
    }

    const key = V.canonicalStringify([
      row.proof_type,
      row.target_test_impact_id,
      coveredChangeImpactIds,
      row.expected,
    ]);
    if (seen.has(key)) V.fail('VNEXT_PLAN_PROOF_DUPLICATE', row.proof_type);
    seen.add(key);

    normalized.push({
      proof_id: V.stableId('PROOF', [
        requirementId,
        row.proof_type,
        row.target_test_impact_id,
        coveredChangeImpactIds,
        row.expected,
      ]),
      proof_type: row.proof_type,
      target_test_impact_id: row.target_test_impact_id,
      covered_change_impact_ids: coveredChangeImpactIds,
      expected: row.expected,
      justification: row.justification,
    });
  });

  const functionalTargets = new Set(
    normalized
      .filter((proof) => proof.proof_type === 'FUNCTIONAL_TEST')
      .map((proof) => proof.target_test_impact_id),
  );
  for (const test of tests) {
    if (test.target_impact_id !== null
        && test.action !== 'REMOVE'
        && !functionalTargets.has(test.target_impact_id)) {
      V.fail('VNEXT_PLAN_FUNCTIONAL_PROOF_MISSING', test.target_impact_id);
    }
  }

  const proofCoveredChanges = new Set(normalized.flatMap((proof) => proof.covered_change_impact_ids));
  for (const impactId of allChangedImpactIds) {
    if (!proofCoveredChanges.has(impactId)) V.fail('VNEXT_PLAN_CHANGE_WITHOUT_PROOF_COVERAGE', impactId);
  }

  if (tests.some((test) => ['NONE_WITH_JUSTIFICATION', 'REMOVE'].includes(test.action))
      && !normalized.some((proof) => proof.proof_type !== 'FUNCTIONAL_TEST')) {
    V.fail('VNEXT_PLAN_ALTERNATIVE_PROOF_REQUIRED', requirementId);
  }

  return normalized.sort((a, b) => a.proof_id.localeCompare(b.proof_id));
}

function normalizeTextList(values, code, label) {
  return uniqueIds(values, code, label, { allowEmpty: true }).map((value) => {
    V.assertUnicodeExactText(value, code, label);
    return value;
  });
}

function buildBoundaries(impactGraph, candidateManifest) {
  const candidates = candidateIndex(candidateManifest);
  const writeKinds = new Map();
  const preserveIds = new Set();

  for (const impact of impactGraph.impacts) {
    if (impact.candidate_id && ['MODIFY', 'CREATE', 'DELETE'].includes(impact.change_kind)) {
      const existing = writeKinds.get(impact.candidate_id);
      if (existing && existing !== impact.change_kind) {
        V.fail(
          'VNEXT_PLAN_BOUNDARY_CHANGE_KIND_CONFLICT',
          `${impact.candidate_id}:${existing}:${impact.change_kind}`,
        );
      }
      writeKinds.set(impact.candidate_id, impact.change_kind);
    }
    for (const candidateId of impact.preservation_candidate_ids || []) preserveIds.add(candidateId);
  }

  for (const candidateId of preserveIds) {
    if (writeKinds.has(candidateId)) V.fail('VNEXT_PLAN_BOUNDARY_CHANGE_PRESERVE_CONFLICT', candidateId);
    const candidate = candidates.get(candidateId);
    if (!candidate) V.fail('VNEXT_PLAN_BOUNDARY_PRESERVE_UNKNOWN', candidateId);
    if (candidate.origin !== 'GIT_TREE') V.fail('VNEXT_PLAN_BOUNDARY_PRESERVE_NON_EXISTING', candidateId);
  }

  const writeScope = [...writeKinds.entries()].map(([candidateId, changeKind]) => {
    const candidate = candidates.get(candidateId);
    if (!candidate) V.fail('VNEXT_PLAN_BOUNDARY_CHANGE_UNKNOWN', candidateId);
    return {
      candidate_id: candidateId,
      path: candidate.path,
      change_kind: changeKind,
    };
  }).sort((a, b) => a.path.localeCompare(b.path));

  const preserveScope = [...preserveIds].map((candidateId) => {
    const candidate = candidates.get(candidateId);
    return { candidate_id: candidateId, path: candidate.path };
  }).sort((a, b) => a.path.localeCompare(b.path));

  return {
    write_scope: writeScope,
    preserve_scope: preserveScope,
    forbidden_policy: FORBIDDEN_POLICY,
  };
}

function buildPlanContract({
  requirementRegistry,
  impactGraph,
  candidateManifest,
  requirementPlans,
}) {
  RequirementRegistry.assertReady(requirementRegistry);
  Impact.validateCandidateManifest(candidateManifest);
  if (impactGraph.requirement_registry_hash !== requirementRegistry.contract_hash) {
    V.fail('VNEXT_PLAN_REQUIREMENT_REGISTRY_HASH_MISMATCH');
  }
  if (impactGraph.candidate_manifest_hash !== candidateManifest.contract_hash) {
    V.fail('VNEXT_PLAN_CANDIDATE_MANIFEST_HASH_MISMATCH');
  }
  V.verifyContractHash(impactGraph, 'VNEXT_PLAN_IMPACT_GRAPH_HASH_MISMATCH');
  if (!Array.isArray(requirementPlans)) V.fail('VNEXT_PLAN_REQUIREMENT_PLANS_INVALID');

  const requirements = new Map(requirementRegistry.requirements.map((req) => [req.requirement_id, req]));
  const impacts = impactIndex(impactGraph);
  const rows = new Map();

  for (const input of requirementPlans) {
    V.assertExactKeys(
      input,
      [
        'requirement_id', 'implementation_intents', 'test_obligations', 'proof_obligations',
        'implementation_constraints', 'residual_risks', 'rationale',
      ],
      [],
      'VNEXT_PLAN_REQUIREMENT_PLAN_KEYS_INVALID',
    );
    const requirement = requirements.get(input.requirement_id);
    if (!requirement) V.fail('VNEXT_PLAN_REQUIREMENT_UNKNOWN', input.requirement_id);
    if (rows.has(input.requirement_id)) V.fail('VNEXT_PLAN_REQUIREMENT_DUPLICATE', input.requirement_id);

    const requirementImpacts = impacts.byRequirement.get(input.requirement_id) || [];
    if (requirementImpacts.length === 0) V.fail('VNEXT_PLAN_REQUIREMENT_IMPACT_MISSING', input.requirement_id);
    const changedImpacts = requirementImpacts.filter((impact) =>
      ['MODIFY', 'CREATE', 'DELETE'].includes(impact.change_kind));
    const disposition = changedImpacts.length > 0 ? 'CHANGE' : 'NO_CHANGE';

    if (disposition === 'NO_CHANGE'
        && requirementImpacts.some((impact) => impact.change_kind !== 'NO_CHANGE')) {
      V.fail('VNEXT_PLAN_NO_CHANGE_CONTRADICTION', input.requirement_id);
    }

    const intents = normalizeImplementationIntents(
      input.implementation_intents,
      input.requirement_id,
      changedImpacts,
    );
    const intentByImpact = new Map(intents.map((row) => [row.impact_id, row.intent]));
    const changeItems = changedImpacts.map((impact) => ({
      change_id: V.stableId('CHG', [input.requirement_id, impact.impact_id]),
      impact_id: impact.impact_id,
      candidate_id: impact.candidate_id,
      path: impact.path,
      change_kind: impact.change_kind,
      intent: intentByImpact.get(impact.impact_id),
    })).sort((a, b) => a.change_id.localeCompare(b.change_id));

    const tests = normalizeTestObligations(
      input.test_obligations,
      input.requirement_id,
      requirementImpacts,
    );
    const proofs = normalizeProofObligations(
      input.proof_obligations,
      input.requirement_id,
      tests,
    );
    const constraints = normalizeTextList(
      input.implementation_constraints,
      'VNEXT_PLAN_CONSTRAINTS_INVALID',
      'implementation_constraints',
    );
    const risks = normalizeTextList(
      input.residual_risks,
      'VNEXT_PLAN_RESIDUAL_RISKS_INVALID',
      'residual_risks',
    );
    V.assertUnicodeExactText(input.rationale, 'VNEXT_PLAN_RATIONALE_INVALID', 'rationale');

    rows.set(input.requirement_id, {
      plan_item_id: V.stableId('PLAN', [
        input.requirement_id,
      ]),
      requirement_id: input.requirement_id,
      requirement_kind: requirement.kind,
      disposition,
      impact_ids: requirementImpacts.map((impact) => impact.impact_id).sort(),
      change_items: changeItems,
      test_obligations: tests,
      proof_obligations: proofs,
      implementation_constraints: constraints,
      residual_risks: risks,
      rationale: input.rationale,
    });
  }

  if (rows.size !== requirements.size) {
    const missing = [...requirements.keys()].filter((id) => !rows.has(id));
    V.fail('VNEXT_PLAN_REQUIREMENT_UNCOVERED', missing.join(','));
  }

  const planItems = [...rows.values()].sort((a, b) => a.requirement_id.localeCompare(b.requirement_id));
  const boundaries = buildBoundaries(impactGraph, candidateManifest);

  return V.sealContract({
    schema_version: SCHEMA,
    requirement_registry_hash: requirementRegistry.contract_hash,
    impact_graph_hash: impactGraph.contract_hash,
    candidate_manifest_hash: candidateManifest.contract_hash,
    requirement_count: requirements.size,
    plan_item_count: planItems.length,
    plan_items: planItems,
    boundaries,
  });
}

function validatePlanContract(planContract, {
  requirementRegistry,
  impactGraph,
  candidateManifest,
}) {
  V.assertExactKeys(
    planContract,
    [
      'schema_version', 'requirement_registry_hash', 'impact_graph_hash',
      'candidate_manifest_hash', 'requirement_count', 'plan_item_count',
      'plan_items', 'boundaries', 'contract_hash',
    ],
    [],
    'VNEXT_PLAN_CONTRACT_KEYS_INVALID',
  );
  if (planContract.schema_version !== SCHEMA) V.fail('VNEXT_PLAN_CONTRACT_SCHEMA_INVALID');
  V.verifyContractHash(planContract, 'VNEXT_PLAN_CONTRACT_HASH_MISMATCH');
  if (planContract.requirement_registry_hash !== requirementRegistry.contract_hash) {
    V.fail('VNEXT_PLAN_REQUIREMENT_REGISTRY_HASH_MISMATCH');
  }
  if (planContract.impact_graph_hash !== impactGraph.contract_hash) {
    V.fail('VNEXT_PLAN_IMPACT_GRAPH_HASH_MISMATCH');
  }
  if (planContract.candidate_manifest_hash !== candidateManifest.contract_hash) {
    V.fail('VNEXT_PLAN_CANDIDATE_MANIFEST_HASH_MISMATCH');
  }

  const requirementPlans = planContract.plan_items.map((item) => ({
    requirement_id: item.requirement_id,
    implementation_intents: item.change_items.map((change) => ({
      impact_id: change.impact_id,
      intent: change.intent,
    })),
    test_obligations: item.test_obligations.map((test) => ({
      target_impact_id: test.target_impact_id,
      covered_change_impact_ids: test.covered_change_impact_ids,
      expected: test.expected,
      justification: test.justification,
    })),
    proof_obligations: item.proof_obligations.map((proof) => ({
      proof_type: proof.proof_type,
      target_test_impact_id: proof.target_test_impact_id,
      covered_change_impact_ids: proof.covered_change_impact_ids,
      expected: proof.expected,
      justification: proof.justification,
    })),
    implementation_constraints: item.implementation_constraints,
    residual_risks: item.residual_risks,
    rationale: item.rationale,
  }));

  const rebuilt = buildPlanContract({
    requirementRegistry,
    impactGraph,
    candidateManifest,
    requirementPlans,
  });
  if (V.canonicalStringify(rebuilt) !== V.canonicalStringify(planContract)) {
    V.fail('VNEXT_PLAN_CONTRACT_REBUILD_MISMATCH');
  }
  return true;
}

function renderMarkdown(planContract) {
  V.verifyContractHash(planContract, 'VNEXT_PLAN_CONTRACT_HASH_MISMATCH');
  const lines = [
    '# KODJO VNext — Plan canonique',
    '',
    `- schema: \`${planContract.schema_version}\``,
    `- contract_hash: \`${planContract.contract_hash}\``,
    `- requirements: ${planContract.requirement_count}`,
    `- write_scope: ${planContract.boundaries.write_scope.length}`,
    '',
    '## Boundaries',
    '',
    `- forbidden_policy: \`${planContract.boundaries.forbidden_policy}\``,
  ];

  for (const row of planContract.boundaries.write_scope) {
    lines.push(`- CHANGE \`${row.path}\` (${row.change_kind})`);
  }
  for (const row of planContract.boundaries.preserve_scope) {
    lines.push(`- PRESERVE \`${row.path}\``);
  }

  for (const item of planContract.plan_items) {
    lines.push('', `## ${item.requirement_id}`, '');
    lines.push(`- disposition: \`${item.disposition}\``);
    lines.push(`- kind: \`${item.requirement_kind}\``);
    lines.push(`- rationale: ${item.rationale}`);
    lines.push('- impacts:');
    for (const id of item.impact_ids) lines.push(`  - \`${id}\``);
    lines.push('- changes:');
    if (item.change_items.length === 0) lines.push('  - none');
    for (const change of item.change_items) {
      lines.push(`  - \`${change.path}\` — ${change.change_kind} — ${change.intent}`);
    }
    lines.push('- tests:');
    for (const test of item.test_obligations) {
      const target = test.path === null ? 'none' : `\`${test.path}\``;
      lines.push(`  - ${test.action} — ${target} — ${test.expected}`);
    }
    lines.push('- proofs:');
    for (const proof of item.proof_obligations) {
      lines.push(`  - ${proof.proof_type} — ${proof.expected}`);
    }
    lines.push('- constraints:');
    if (item.implementation_constraints.length === 0) lines.push('  - none');
    for (const value of item.implementation_constraints) lines.push(`  - ${value}`);
    lines.push('- residual_risks:');
    if (item.residual_risks.length === 0) lines.push('  - none');
    for (const value of item.residual_risks) lines.push(`  - ${value}`);
  }

  lines.push(
    '',
    '<KODJO_VNEXT_PLAN_CONTRACT_JSON>',
    JSON.stringify(planContract, null, 2),
    '</KODJO_VNEXT_PLAN_CONTRACT_JSON>',
    '',
  );
  return lines.join('\n');
}

function verifyMarkdownProjection(markdown, planContract) {
  if (String(markdown) !== renderMarkdown(planContract)) {
    V.fail('VNEXT_PLAN_MARKDOWN_PROJECTION_DRIFT');
  }
  return true;
}

module.exports = {
  SCHEMA,
  DISPOSITIONS,
  PROOF_TYPES,
  TEST_ACTIONS,
  FORBIDDEN_POLICY,
  isTestPath,
  buildPlanContract,
  validatePlanContract,
  renderMarkdown,
  verifyMarkdownProjection,
};

'use strict';

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const SCAN_SCHEMA = 'kodjo.direct-import-scan.v1';
const MATRIX_SCHEMA = 'kodjo.plan-impact.v1';
const REVIEW_SCHEMA = 'kodjo.plan-impact-review.v1';
const CLASSIFICATIONS = Object.freeze([
  'MODIFY', 'TEST_MUST_ADAPT', 'CONSUMER_UNAFFECTED',
  'TEST_UNAFFECTED', 'REQUIRES_CLARIFICATION',
]);
const SOURCE_EXTENSIONS = Object.freeze(['.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs']);
const compareText = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

function fail(code, detail) {
  const error = new Error(code + (detail ? ': ' + detail : ''));
  error.code = code;
  throw error;
}

function normalizeRepoPath(value, label = 'path') {
  if (typeof value !== 'string' || value.length === 0) fail('PLAN_SCAN_PATH_INVALID', label + ' vide');
  if (value.includes('\\') || value.startsWith('/') || /^[A-Za-z]:/.test(value)) {
    fail('PLAN_SCAN_PATH_AMBIGUOUS', label + '=' + value);
  }
  const parts = value.split('/');
  if (parts.some((part) => part === '' || part === '.' || part === '..')) {
    fail('PLAN_SCAN_PATH_AMBIGUOUS', label + '=' + value);
  }
  const normalized = path.posix.normalize(value);
  if (normalized !== value || normalized.startsWith('../')) fail('PLAN_SCAN_PATH_AMBIGUOUS', label + '=' + value);
  return normalized;
}

function git(args, cwd, encoding = 'utf8') {
  const result = spawnSync('git', args, {
    cwd, encoding, windowsHide: true, shell: false, maxBuffer: 64 * 1024 * 1024,
  });
  if (result.error || result.status !== 0) {
    fail('PLAN_SCAN_GIT_FAILED', 'git ' + args.join(' ') + ': ' + String(result.stderr || result.error?.message || '').trim());
  }
  return result.stdout;
}

function canonicalJson(value) {
  if (Array.isArray(value)) return '[' + value.map(canonicalJson).join(',') + ']';
  if (value && typeof value === 'object') {
    return '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + canonicalJson(value[key])).join(',') + '}';
  }
  return JSON.stringify(value);
}

function sha256(value) {
  return crypto.createHash('sha256').update(canonicalJson(value), 'utf8').digest('hex');
}

function normalizeModules(input) {
  if (!Array.isArray(input) || input.length === 0) fail('PLAN_SCOPE_UNCLASSIFIED', 'modified_modules vide');
  const seen = new Set();
  return input.map((entry) => {
    const item = typeof entry === 'string' ? { path: entry, change: 'MODIFY' } : entry;
    if (!item || typeof item !== 'object') fail('PLAN_SCAN_PATH_INVALID', 'module invalide');
    const modulePath = normalizeRepoPath(item.path, 'modified_module');
    const change = String(item.change || 'MODIFY').toUpperCase();
    if (!['MODIFY', 'CREATE'].includes(change)) fail('PLAN_SCOPE_CONTRADICTION', 'change inconnu pour ' + modulePath);
    if (seen.has(modulePath)) fail('PLAN_SCOPE_CONTRADICTION', 'module duplique: ' + modulePath);
    seen.add(modulePath);
    return { path: modulePath, change };
  }).sort((a, b) => compareText(a.path, b.path));
}

function extractSpecifiers(source) {
  const specs = new Set();
  const patterns = [
    /\b(?:import|export)\s+(?:type\s+)?(?:[\s\S]*?\s+from\s+)?["']([^"']+)["']/g,
    /\b(?:require|import)\s*\(\s*["']([^"']+)["']\s*\)/g,
    /\bjest\.(?:mock|unmock|requireActual)\s*\(\s*["']([^"']+)["']/g,
  ];
  for (const pattern of patterns) {
    let match;
    while ((match = pattern.exec(source)) !== null) specs.add(match[1]);
  }
  return [...specs].sort(compareText);
}

function resolveSpecifier(importer, specifier, fileSet) {
  let base;
  if (specifier.startsWith('@/')) base = 'src/' + specifier.slice(2);
  else if (specifier.startsWith('.')) {
    base = path.posix.normalize(path.posix.join(path.posix.dirname(importer), specifier));
    if (base === '..' || base.startsWith('../')) fail('PLAN_SCAN_PATH_AMBIGUOUS', importer + ' -> ' + specifier);
  } else return null;

  const candidates = [];
  const add = (candidate) => { if (fileSet.has(candidate)) candidates.push(candidate); };
  add(base);
  if (!SOURCE_EXTENSIONS.some((ext) => base.endsWith(ext))) {
    for (const ext of SOURCE_EXTENSIONS) add(base + ext);
    for (const ext of SOURCE_EXTENSIONS) add(base + '/index' + ext);
  }
  const unique = [...new Set(candidates)].sort(compareText);
  if (unique.length > 1) fail('PLAN_SCAN_PATH_AMBIGUOUS', importer + ' -> ' + specifier + ': ' + unique.join(', '));
  return unique[0] || null;
}

function riskScore(file, source) {
  let score = /(?:^|\/)(__tests__|tests?)\//.test(file) || /\.(?:test|spec)\.[^.]+$/.test(file) ? 100 : 0;
  score += Math.min(30, (source.match(/\bexpect\s*\(/g) || []).length * 3);
  score += Math.min(20, (source.match(/(?:toEqual|toStrictEqual|toMatchObject)\s*\(/g) || []).length * 2);
  return score;
}

function scanDirectImporters(options) {
  const cwd = options.cwd || process.cwd();
  const revision = String(options.revision || '');
  if (!/^[0-9a-f]{40}$/i.test(revision)) fail('PLAN_SCAN_STALE', 'revision Git invalide: ' + revision);
  git(['cat-file', '-e', revision + '^{commit}'], cwd);
  const modules = normalizeModules(options.modifiedModules);
  const rawTree = git(['ls-tree', '-r', '-z', revision, '--', 'app', 'src'], cwd, 'buffer');
  const applicationTreeSha256 = crypto.createHash('sha256').update(rawTree).digest('hex');
  const rawFiles = git(['ls-tree', '-r', '--name-only', '-z', revision, '--', 'app', 'src'], cwd, 'buffer');
  const files = rawFiles.toString('utf8').split('\0').filter(Boolean).map((file) => normalizeRepoPath(file)).sort(compareText);
  const fileSet = new Set(files);
  for (const module of modules) {
    if (module.change === 'MODIFY' && !fileSet.has(module.path)) {
      fail('PLAN_SCAN_PATH_INVALID', 'module MODIFY absent a ' + revision + ': ' + module.path);
    }
    if (module.change === 'CREATE' && fileSet.has(module.path)) {
      fail('PLAN_SCOPE_CONTRADICTION', 'module CREATE existe deja: ' + module.path);
    }
  }
  const targetSet = new Set(modules.filter((module) => module.change === 'MODIFY').map((module) => module.path));
  const candidates = [];
  for (const file of files) {
    if (!SOURCE_EXTENSIONS.some((ext) => file.endsWith(ext))) continue;
    const source = String(git(['show', revision + ':' + file], cwd));
    const triggeredBy = extractSpecifiers(source)
      .map((specifier) => resolveSpecifier(file, specifier, fileSet))
      .filter((resolved) => resolved && targetSet.has(resolved));
    const unique = [...new Set(triggeredBy)].sort(compareText);
    if (unique.length === 0 || targetSet.has(file)) continue;
    const isTest = /(?:^|\/)(__tests__|tests?)\//.test(file) || /\.(?:test|spec)\.[^.]+$/.test(file);
    candidates.push({
      path: file,
      candidate_kind: isTest ? 'TEST' : 'CONSUMER',
      triggered_by: unique,
      risk_score: riskScore(file, source),
    });
  }
  candidates.sort((a, b) => b.risk_score - a.risk_score || compareText(a.path, b.path));
  return {
    schema: SCAN_SCHEMA,
    scan_revision: revision.toLowerCase(),
    application_tree_sha256: applicationTreeSha256,
    modified_modules: modules,
    candidates,
  };
}

function extractTaggedJson(markdown, tag, missingCode = 'PLAN_SCOPE_UNCLASSIFIED') {
  const escaped = tag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const matches = [...String(markdown).matchAll(new RegExp('<' + escaped + '>\\s*([\\s\\S]*?)\\s*</' + escaped + '>', 'g'))];
  if (matches.length !== 1) fail(missingCode, tag + ' attendu exactement une fois, trouve ' + matches.length);
  try { return JSON.parse(matches[0][1]); } catch (error) { fail(missingCode, tag + ' JSON invalide: ' + error.message); }
}

function rowSignature(row) {
  return canonicalJson({
    path: row.path,
    candidate_kind: row.candidate_kind,
    triggered_by: row.triggered_by,
    risk_score: row.risk_score,
  });
}

function verifyImpactMatrix(matrix, replayScan, expectedRevision) {
  if (!matrix || matrix.schema !== MATRIX_SCHEMA) fail('PLAN_SCOPE_UNCLASSIFIED', 'schema de matrice absent ou inconnu');
  const expected = String(expectedRevision || '').toLowerCase();
  if (matrix.scan_revision !== expected || replayScan.scan_revision !== expected) {
    fail('PLAN_SCAN_STALE', 'matrice=' + matrix.scan_revision + ', rejeu=' + replayScan.scan_revision + ', source_head=' + expected);
  }
  const modules = normalizeModules(matrix.modified_modules);
  if (canonicalJson(modules) !== canonicalJson(replayScan.modified_modules)) {
    fail('PLAN_SCOPE_CONTRADICTION', 'modified_modules differe du rejeu');
  }
  const replayHash = sha256(replayScan);
  if (matrix.scan_sha256 !== replayHash) fail('PLAN_SCOPE_CONTRADICTION', 'scan_sha256 differe du rejeu');
  if (!Array.isArray(matrix.rows)) fail('PLAN_SCOPE_UNCLASSIFIED', 'rows absent');

  const expectedRows = [
    ...modules.map((module) => ({ path: module.path, candidate_kind: 'MODIFIED_MODULE', triggered_by: [], risk_score: 0 })),
    ...replayScan.candidates,
  ];
  const rows = new Map();
  for (const row of matrix.rows) {
    const rowPath = normalizeRepoPath(row.path, 'matrix.row.path');
    if (rows.has(rowPath)) fail('PLAN_SCOPE_CONTRADICTION', 'ligne dupliquee: ' + rowPath);
    if (!CLASSIFICATIONS.includes(row.classification)) fail('PLAN_SCOPE_UNCLASSIFIED', rowPath + ': classification absente ou inconnue');
    if (row.classification === 'REQUIRES_CLARIFICATION') fail('PLAN_SCOPE_UNCLASSIFIED', rowPath + ': clarification requise');
    if (typeof row.justification !== 'string' || row.justification.trim().length === 0) {
      fail('PLAN_SCOPE_UNCLASSIFIED', rowPath + ': justification positive absente');
    }
    rows.set(rowPath, { ...row, path: rowPath });
  }
  if (rows.size > expectedRows.length) fail('PLAN_SCOPE_CONTRADICTION', 'la matrice contient des lignes absentes du scan');
  for (const expectedRow of expectedRows) {
    const actual = rows.get(expectedRow.path);
    if (!actual) fail('PLAN_SCOPE_UNCLASSIFIED', 'candidat non classe: ' + expectedRow.path);
    if (rowSignature(actual) !== rowSignature(expectedRow)) {
      fail('PLAN_SCOPE_CONTRADICTION', 'preuve de candidat alteree: ' + expectedRow.path);
    }
    if (expectedRow.candidate_kind === 'MODIFIED_MODULE' && actual.classification !== 'MODIFY') {
      fail('PLAN_SCOPE_CONTRADICTION', expectedRow.path + ' doit etre MODIFY');
    }
    if (expectedRow.candidate_kind === 'TEST' && !['TEST_MUST_ADAPT', 'TEST_UNAFFECTED'].includes(actual.classification)) {
      fail('PLAN_SCOPE_CONTRADICTION', expectedRow.path + ': classification de test incompatible');
    }
    if (expectedRow.candidate_kind === 'CONSUMER' && !['MODIFY', 'CONSUMER_UNAFFECTED'].includes(actual.classification)) {
      fail('PLAN_SCOPE_CONTRADICTION', expectedRow.path + ': classification de consommateur incompatible');
    }
  }
  if (rows.size !== expectedRows.length) fail('PLAN_SCOPE_CONTRADICTION', 'cardinalite de matrice differente du scan');
  if (!Array.isArray(matrix.scope_allow)) fail('PLAN_SCOPE_CONTRADICTION', 'scope_allow absent');
  const actualScope = matrix.scope_allow.map((p) => normalizeRepoPath(p, 'scope_allow')).sort();
  if (new Set(actualScope).size !== actualScope.length) fail('PLAN_SCOPE_CONTRADICTION', 'scope_allow contient un doublon');
  const expectedScope = [...rows.values()]
    .filter((row) => ['MODIFY', 'TEST_MUST_ADAPT'].includes(row.classification))
    .map((row) => row.path).sort();
  if (canonicalJson(actualScope) !== canonicalJson(expectedScope)) {
    fail('PLAN_SCOPE_CONTRADICTION', 'scope_allow != MODIFY union TEST_MUST_ADAPT');
  }
  return { matrix, replay_scan: replayScan, scan_sha256: replayHash, scope_allow: expectedScope };
}

function buildReviewProof(verified) {
  return {
    schema: REVIEW_SCHEMA,
    scan_revision: verified.replay_scan.scan_revision,
    plan_scan_sha256: verified.matrix.scan_sha256,
    reviewer_scan_sha256: verified.scan_sha256,
    candidate_count: verified.replay_scan.candidates.length,
    verdict: 'MATCH',
  };
}

function verifyReviewProof(proof, verified) {
  if (!proof || proof.schema !== REVIEW_SCHEMA) fail('PLAN_SCOPE_CONTRADICTION', 'preuve de revue absente ou inconnue');
  const expected = buildReviewProof(verified);
  if (canonicalJson(proof) !== canonicalJson(expected)) fail('PLAN_SCOPE_CONTRADICTION', 'preuve de revue differente du rejeu');
  return expected;
}

function verifyPlanAtRevision(options) {
  const matrix = extractTaggedJson(options.planMarkdown, 'KODJO_PLAN_IMPACT_JSON');
  const replay = scanDirectImporters({
    cwd: options.cwd,
    revision: matrix.scan_revision,
    modifiedModules: matrix.modified_modules,
  });
  const verified = verifyImpactMatrix(matrix, replay, matrix.scan_revision);
  const sourceReplay = scanDirectImporters({
    cwd: options.cwd,
    revision: options.sourceHead,
    modifiedModules: matrix.modified_modules,
  });
  if (sourceReplay.application_tree_sha256 !== replay.application_tree_sha256) {
    fail('PLAN_SCAN_STALE', 'baseline applicative modifiee entre ' + matrix.scan_revision + ' et ' + options.sourceHead);
  }
  const comparableSourceReplay = { ...sourceReplay, scan_revision: replay.scan_revision };
  if (sha256(comparableSourceReplay) !== sha256(replay)) {
    fail('PLAN_SCOPE_CONTRADICTION', 'le rejeu a source_head differe malgre une empreinte applicative identique');
  }
  verified.source_scan = sourceReplay;
  if (options.reviewMarkdown !== undefined) {
    const proof = extractTaggedJson(options.reviewMarkdown, 'KODJO_PLAN_IMPACT_REVIEW_JSON', 'PLAN_SCOPE_CONTRADICTION');
    verifyReviewProof(proof, verified);
  }
  return verified;
}

module.exports = {
  SCAN_SCHEMA, MATRIX_SCHEMA, REVIEW_SCHEMA, CLASSIFICATIONS,
  normalizeRepoPath, normalizeModules, extractSpecifiers, resolveSpecifier,
  canonicalJson, sha256, scanDirectImporters, extractTaggedJson,
  verifyImpactMatrix, buildReviewProof, verifyReviewProof, verifyPlanAtRevision, fail,
};

'use strict';

const V = require('./vnext-contract');
const SourceManifest = require('./source-manifest');

const SCHEMA = 'kodjo.vnext.planning-envelope.v1';
const MODES = Object.freeze(['INITIAL', 'REVISION']);
const CREATED_FROM_KINDS = Object.freeze(['INITIAL_REQUEST', 'PLAN_REVIEW_REVISE', 'CLARIFICATION_RESOLVED']);

function validateCreatedFrom(value) {
  V.assertExactKeys(value, ['kind', 'refs'], [], 'VNEXT_CREATED_FROM_KEYS_INVALID');
  if (!CREATED_FROM_KINDS.includes(value.kind)) V.fail('VNEXT_CREATED_FROM_KIND_INVALID', value.kind);
  return Object.freeze({ kind: value.kind, refs: V.uniqueStrings(value.refs, 'VNEXT_CREATED_FROM_REFS_INVALID', 'created_from.refs') });
}

function build(input) {
  V.assertExactKeys(input, [
    'slice_id', 'planning_mode', 'baseline_head', 'product_head', 'application_head', 'issue_id',
    'source_manifest', 'base_plan_hash', 'base_review_hash', 'causal_findings', 'created_from',
  ], [], 'VNEXT_PLANNING_ENVELOPE_INPUT_INVALID');

  V.assertSliceId(input.slice_id);
  if (!MODES.includes(input.planning_mode)) V.fail('VNEXT_PLANNING_MODE_INVALID', input.planning_mode);
  V.assertSha40(input.baseline_head, 'VNEXT_BASELINE_HEAD_INVALID', 'baseline_head');
  V.assertSha40(input.product_head, 'VNEXT_PRODUCT_HEAD_INVALID', 'product_head');
  V.assertSha40(input.application_head, 'VNEXT_APPLICATION_HEAD_INVALID', 'application_head');
  V.assertUnicodeExactText(input.issue_id, 'VNEXT_ISSUE_ID_INVALID', 'issue_id');
  SourceManifest.validate(input.source_manifest);
  if (input.source_manifest.slice_id !== input.slice_id) V.fail('VNEXT_SOURCE_MANIFEST_SLICE_MISMATCH');
  if (input.source_manifest.product_head !== input.product_head) V.fail('VNEXT_SOURCE_MANIFEST_HEAD_MISMATCH');
  const createdFrom = validateCreatedFrom(input.created_from);

  let basePlanHash = input.base_plan_hash;
  let baseReviewHash = input.base_review_hash;
  let causalFindings = input.causal_findings;

  if (input.planning_mode === 'INITIAL') {
    if (basePlanHash !== null || baseReviewHash !== null) V.fail('VNEXT_INITIAL_CAUSAL_BASE_FORBIDDEN');
    if (!Array.isArray(causalFindings) || causalFindings.length !== 0) V.fail('VNEXT_INITIAL_FINDINGS_FORBIDDEN');
    if (createdFrom.kind !== 'INITIAL_REQUEST') V.fail('VNEXT_INITIAL_CREATED_FROM_INVALID');
  } else {
    V.assertSha64(basePlanHash, 'VNEXT_REVISION_BASE_PLAN_INVALID', 'base_plan_hash');
    V.assertSha64(baseReviewHash, 'VNEXT_REVISION_BASE_REVIEW_INVALID', 'base_review_hash');
    causalFindings = V.uniqueStrings(causalFindings, 'VNEXT_REVISION_FINDINGS_INVALID', 'causal_findings');
    if (!['PLAN_REVIEW_REVISE', 'CLARIFICATION_RESOLVED'].includes(createdFrom.kind)) {
      V.fail('VNEXT_REVISION_CREATED_FROM_INVALID', createdFrom.kind);
    }
  }

  return V.sealContract({
    schema_version: SCHEMA,
    slice_id: input.slice_id,
    planning_mode: input.planning_mode,
    baseline_head: input.baseline_head,
    product_head: input.product_head,
    application_head: input.application_head,
    issue_id: input.issue_id,
    source_manifest: input.source_manifest,
    base_plan_hash: basePlanHash,
    base_review_hash: baseReviewHash,
    causal_findings: causalFindings,
    created_from: createdFrom,
  });
}

function validate(envelope) {
  V.assertExactKeys(envelope, [
    'schema_version', 'slice_id', 'planning_mode', 'baseline_head', 'product_head', 'application_head', 'issue_id',
    'source_manifest', 'base_plan_hash', 'base_review_hash', 'causal_findings', 'created_from', 'contract_hash',
  ], [], 'VNEXT_PLANNING_ENVELOPE_KEYS_INVALID');
  if (envelope.schema_version !== SCHEMA) V.fail('VNEXT_PLANNING_ENVELOPE_SCHEMA_INVALID', envelope.schema_version);
  V.verifyContractHash(envelope, 'VNEXT_PLANNING_ENVELOPE_HASH_MISMATCH');
  const rebuilt = build({
    slice_id: envelope.slice_id, planning_mode: envelope.planning_mode, baseline_head: envelope.baseline_head,
    product_head: envelope.product_head, application_head: envelope.application_head, issue_id: envelope.issue_id,
    source_manifest: envelope.source_manifest, base_plan_hash: envelope.base_plan_hash, base_review_hash: envelope.base_review_hash,
    causal_findings: envelope.causal_findings, created_from: envelope.created_from,
  });
  if (V.canonicalStringify(rebuilt) !== V.canonicalStringify(envelope)) V.fail('VNEXT_PLANNING_ENVELOPE_REBUILD_MISMATCH');
  return true;
}

module.exports = { SCHEMA, MODES, CREATED_FROM_KINDS, build, validate };

'use strict';

const V = require('./vnext-contract');
const SourceManifest = require('./source-manifest');

const SCHEMA = 'kodjo.vnext.requirement-registry.v1';
const REQUIREMENT_KINDS = Object.freeze([
  'FUNCTIONAL',
  'UI',
  'DATA',
  'TECHNICAL',
  'MIGRATION',
  'PRESERVATION',
  'NON_FUNCTIONAL',
]);
const REQUIREMENT_STATUSES = Object.freeze(['ACTIVE', 'CLARIFICATION_REQUIRED']);
const PRIORITIES = Object.freeze(['MUST', 'SHOULD', 'MAY', 'UNSPECIFIED']);
const REGISTRY_STATUSES = Object.freeze(['READY', 'BLOCKED']);

function sourceIndex(manifest) {
  const sources = new Map();
  const units = new Map();
  for (const source of manifest.sources) {
    sources.set(source.source_id, source);
    for (const unit of source.units) {
      if (units.has(unit.unit_id)) V.fail('VNEXT_REQUIREMENT_SOURCE_UNIT_COLLISION', unit.unit_id);
      units.set(unit.unit_id, { source, unit });
    }
  }
  return { sources, units };
}

function validateRequirementInput(row, index, indexData) {
  V.assertExactKeys(
    row,
    [
      'source_id', 'unit_id', 'kind', 'statement', 'priority', 'status', 'rationale',
      'related_unit_ids', 'conflict_unit_ids',
    ],
    [],
    'VNEXT_REQUIREMENT_INPUT_KEYS_INVALID',
  );

  const source = indexData.sources.get(row.source_id);
  const located = indexData.units.get(row.unit_id);
  if (!source) V.fail('VNEXT_REQUIREMENT_SOURCE_UNKNOWN', row.source_id);
  if (!located || located.source.source_id !== row.source_id) {
    V.fail('VNEXT_REQUIREMENT_UNIT_SOURCE_MISMATCH', String(row.unit_id));
  }

  const disposition = located.unit.disposition;
  if (!['REQUIREMENT_SOURCE', 'AMBIGUOUS'].includes(disposition)) {
    V.fail('VNEXT_REQUIREMENT_SOURCE_DISPOSITION_FORBIDDEN', `${row.unit_id}:${disposition}`);
  }

  if (!REQUIREMENT_KINDS.includes(row.kind)) V.fail('VNEXT_REQUIREMENT_KIND_INVALID', row.kind);
  V.assertUnicodeExactText(row.statement, 'VNEXT_REQUIREMENT_STATEMENT_INVALID', `requirements[${index}].statement`);
  if (!PRIORITIES.includes(row.priority)) V.fail('VNEXT_REQUIREMENT_PRIORITY_INVALID', row.priority);
  if (!REQUIREMENT_STATUSES.includes(row.status)) V.fail('VNEXT_REQUIREMENT_STATUS_INVALID', row.status);
  V.assertUnicodeExactText(row.rationale, 'VNEXT_REQUIREMENT_RATIONALE_INVALID', `requirements[${index}].rationale`);

  if (disposition === 'REQUIREMENT_SOURCE' && row.status !== 'ACTIVE') {
    V.fail('VNEXT_REQUIREMENT_SOURCE_STATUS_MISMATCH', row.unit_id);
  }
  if (disposition === 'AMBIGUOUS' && row.status !== 'CLARIFICATION_REQUIRED') {
    V.fail('VNEXT_AMBIGUOUS_SOURCE_STATUS_MISMATCH', row.unit_id);
  }

  const relatedUnitIds = V.uniqueStrings(
    row.related_unit_ids,
    'VNEXT_REQUIREMENT_RELATED_UNITS_INVALID',
    `requirements[${index}].related_unit_ids`,
    { allowEmpty: true },
  );
  const conflictUnitIds = V.uniqueStrings(
    row.conflict_unit_ids,
    'VNEXT_REQUIREMENT_CONFLICT_UNITS_INVALID',
    `requirements[${index}].conflict_unit_ids`,
    { allowEmpty: true },
  );

  for (const unitId of [...relatedUnitIds, ...conflictUnitIds]) {
    if (unitId === row.unit_id) V.fail('VNEXT_REQUIREMENT_SELF_RELATION', unitId);
    if (!indexData.units.has(unitId)) V.fail('VNEXT_REQUIREMENT_RELATED_UNIT_UNKNOWN', unitId);
  }

  const requirementId = V.stableId('REQ', [
    source.source_id,
    located.unit.unit_id,
    located.unit.fingerprint,
    row.kind,
    row.statement,
  ]);

  return {
    requirement_id: requirementId,
    source_id: source.source_id,
    unit_id: located.unit.unit_id,
    kind: row.kind,
    statement: row.statement,
    priority: row.priority,
    status: row.status,
    preservation: row.kind === 'PRESERVATION' ? 'REQUIRED' : 'NONE_DECLARED',
    rationale: row.rationale,
    related_unit_ids: relatedUnitIds,
    conflict_unit_ids: conflictUnitIds,
    source: {
      source_kind: source.source_kind,
      authority: source.authority,
      locator: source.locator,
      revision: source.revision,
      unit_locator: located.unit.locator,
      unit_fingerprint: located.unit.fingerprint,
      unit_disposition: located.unit.disposition,
    },
  };
}

function build(input) {
  V.assertExactKeys(
    input,
    ['planning_envelope_hash', 'source_manifest', 'requirements'],
    [],
    'VNEXT_REQUIREMENT_REGISTRY_INPUT_INVALID',
  );
  V.assertSha64(input.planning_envelope_hash, 'VNEXT_REQUIREMENT_ENVELOPE_HASH_INVALID', 'planning_envelope_hash');
  SourceManifest.validate(input.source_manifest);
  if (!Array.isArray(input.requirements)) V.fail('VNEXT_REQUIREMENT_ROWS_INVALID');

  const idx = sourceIndex(input.source_manifest);
  const normalized = input.requirements.map((row, index) => validateRequirementInput(row, index, idx));
  const requirementSourceUnits = [...idx.units.values()].filter(({ unit }) =>
    ['REQUIREMENT_SOURCE', 'AMBIGUOUS'].includes(unit.disposition));
  if (requirementSourceUnits.length === 0) V.fail('VNEXT_REQUIREMENT_REGISTRY_EMPTY');

  const ids = normalized.map((row) => row.requirement_id);
  if (new Set(ids).size !== ids.length) V.fail('VNEXT_REQUIREMENT_ID_DUPLICATE');

  const byUnit = new Map();
  for (const req of normalized) {
    const list = byUnit.get(req.unit_id) || [];
    list.push(req.requirement_id);
    byUnit.set(req.unit_id, list);
  }

  const coverage = [];
  for (const source of input.source_manifest.sources) {
    for (const unit of source.units) {
      const requirementIds = [...(byUnit.get(unit.unit_id) || [])].sort();
      if (unit.disposition === 'REQUIREMENT_SOURCE' && requirementIds.length === 0) {
        V.fail('VNEXT_REQUIREMENT_SOURCE_UNCOVERED', unit.unit_id);
      }
      if (unit.disposition === 'AMBIGUOUS' && requirementIds.length === 0) {
        V.fail('VNEXT_AMBIGUOUS_SOURCE_UNCOVERED', unit.unit_id);
      }
      if (['CONTEXT_ONLY', 'SUPERSEDED', 'OUT_OF_SCOPE'].includes(unit.disposition) && requirementIds.length !== 0) {
        V.fail('VNEXT_NON_REQUIREMENT_SOURCE_HAS_REQUIREMENTS', unit.unit_id);
      }
      coverage.push({
        source_id: source.source_id,
        unit_id: unit.unit_id,
        disposition: unit.disposition,
        requirement_ids: requirementIds,
        coverage_status:
          ['REQUIREMENT_SOURCE', 'AMBIGUOUS'].includes(unit.disposition) ? 'COVERED' : 'DISPOSED',
      });
    }
  }

  const requirementIdsByUnit = new Map();
  for (const item of coverage) requirementIdsByUnit.set(item.unit_id, item.requirement_ids);

  const relationMap = new Map(normalized.map((req) => [
    req.requirement_id,
    { related: new Set(), conflicts: new Set() },
  ]));

  for (const req of normalized) {
    for (const unitId of req.related_unit_ids) {
      const targetIds = requirementIdsByUnit.get(unitId) || [];
      if (targetIds.length === 0) V.fail('VNEXT_REQUIREMENT_RELATED_UNIT_UNMAPPED', unitId);
      for (const targetId of targetIds) {
        if (targetId === req.requirement_id) continue;
        relationMap.get(req.requirement_id).related.add(targetId);
        relationMap.get(targetId).related.add(req.requirement_id);
      }
    }
    for (const unitId of req.conflict_unit_ids) {
      const targetIds = requirementIdsByUnit.get(unitId) || [];
      if (targetIds.length === 0) V.fail('VNEXT_REQUIREMENT_CONFLICT_UNIT_UNMAPPED', unitId);
      for (const targetId of targetIds) {
        if (targetId === req.requirement_id) continue;
        relationMap.get(req.requirement_id).conflicts.add(targetId);
        relationMap.get(targetId).conflicts.add(req.requirement_id);
      }
    }
  }

  const requirements = normalized
    .map((req) => ({
      ...req,
      related_requirement_ids: [...relationMap.get(req.requirement_id).related].sort(),
      conflict_ids: [...relationMap.get(req.requirement_id).conflicts].sort(),
    }))
    .sort((a, b) => a.requirement_id.localeCompare(b.requirement_id));

  const blockingReasons = [];
  if (requirements.some((req) => req.status === 'CLARIFICATION_REQUIRED')) {
    blockingReasons.push('CLARIFICATION_REQUIRED');
  }
  if (requirements.some((req) => req.conflict_ids.length > 0)) {
    blockingReasons.push('SOURCE_CONFLICT');
  }

  return V.sealContract({
    schema_version: SCHEMA,
    planning_envelope_hash: input.planning_envelope_hash,
    source_manifest_hash: input.source_manifest.contract_hash,
    registry_status: blockingReasons.length ? 'BLOCKED' : 'READY',
    blocking_reasons: blockingReasons,
    source_unit_count: coverage.length,
    requirement_source_unit_count: coverage.filter((row) =>
      ['REQUIREMENT_SOURCE', 'AMBIGUOUS'].includes(row.disposition)).length,
    requirement_count: requirements.length,
    requirement_ids_sha256: V.canonicalHash(requirements.map((req) => req.requirement_id)),
    coverage,
    requirements,
  });
}

function validate(registry, sourceManifest) {
  V.assertExactKeys(
    registry,
    [
      'schema_version', 'planning_envelope_hash', 'source_manifest_hash', 'registry_status',
      'blocking_reasons', 'source_unit_count', 'requirement_source_unit_count',
      'requirement_count', 'requirement_ids_sha256', 'coverage', 'requirements', 'contract_hash',
    ],
    [],
    'VNEXT_REQUIREMENT_REGISTRY_KEYS_INVALID',
  );
  if (registry.schema_version !== SCHEMA) V.fail('VNEXT_REQUIREMENT_REGISTRY_SCHEMA_INVALID', registry.schema_version);
  if (!REGISTRY_STATUSES.includes(registry.registry_status)) {
    V.fail('VNEXT_REQUIREMENT_REGISTRY_STATUS_INVALID', registry.registry_status);
  }
  V.verifyContractHash(registry, 'VNEXT_REQUIREMENT_REGISTRY_HASH_MISMATCH');
  SourceManifest.validate(sourceManifest);
  if (registry.source_manifest_hash !== sourceManifest.contract_hash) {
    V.fail('VNEXT_REQUIREMENT_SOURCE_MANIFEST_HASH_MISMATCH');
  }

  const rebuilt = build({
    planning_envelope_hash: registry.planning_envelope_hash,
    source_manifest: sourceManifest,
    requirements: registry.requirements.map((req) => ({
      source_id: req.source_id,
      unit_id: req.unit_id,
      kind: req.kind,
      statement: req.statement,
      priority: req.priority,
      status: req.status,
      rationale: req.rationale,
      related_unit_ids: req.related_unit_ids,
      conflict_unit_ids: req.conflict_unit_ids,
    })),
  });
  if (V.canonicalStringify(rebuilt) !== V.canonicalStringify(registry)) {
    V.fail('VNEXT_REQUIREMENT_REGISTRY_REBUILD_MISMATCH');
  }
  return true;
}

function assertReady(registry) {
  if (!registry || registry.registry_status !== 'READY') {
    const reasons = registry && Array.isArray(registry.blocking_reasons) ? registry.blocking_reasons : [];
    if (reasons.includes('CLARIFICATION_REQUIRED')) V.fail('CLARIFICATION_REQUIRED', reasons.join(','));
    if (reasons.includes('SOURCE_CONFLICT')) V.fail('PRODUCT_AMBIGUITY', reasons.join(','));
    V.fail('VNEXT_REQUIREMENTS_NOT_READY', reasons.join(','));
  }
  return true;
}

module.exports = {
  SCHEMA,
  REQUIREMENT_KINDS,
  REQUIREMENT_STATUSES,
  PRIORITIES,
  REGISTRY_STATUSES,
  build,
  validate,
  assertReady,
};

'use strict';

const V = require('./vnext-contract');
const PlanningEnvelope = require('./planning-envelope');
const RequirementRegistry = require('./requirement-registry');
const Impact = require('./impact-graph');
const Plan = require('./plan-contract');
const Ui = require('./ui-atomicity-contract');

const CONTEXT_SCHEMA = 'kodjo.vnext.review-context.v1';
const REPORT_SCHEMA = 'kodjo.vnext.review-report.v1';

const FINDING_CATEGORIES = Object.freeze([
  'MISSING_REQUIREMENT',
  'SOURCE_CONTRADICTION',
  'IMPACT_INCOMPLETE',
  'WRONG_TARGET',
  'PLAN_GAP',
  'TEST_GAP',
  'PROOF_GAP',
  'PRESERVATION_RISK',
  'UI_ASSERTION_GAP',
  'PRODUCT_AMBIGUITY',
  'TECHNICAL_RISK',
  'SUGGESTION',
]);

const TARGET_TYPES = Object.freeze([
  'SOURCE_UNIT',
  'REQUIREMENT',
  'IMPACT',
  'CANDIDATE',
  'PLAN_ITEM',
  'TEST',
  'PROOF',
  'CRITERION',
  'ASSERTION',
  'PLAN_CONTRACT',
]);

const CATEGORY_TARGETS = Object.freeze({
  MISSING_REQUIREMENT: ['SOURCE_UNIT'],
  SOURCE_CONTRADICTION: ['SOURCE_UNIT', 'REQUIREMENT'],
  IMPACT_INCOMPLETE: ['REQUIREMENT', 'IMPACT', 'CANDIDATE'],
  WRONG_TARGET: ['IMPACT', 'CANDIDATE'],
  PLAN_GAP: ['REQUIREMENT', 'PLAN_ITEM', 'PLAN_CONTRACT'],
  TEST_GAP: ['REQUIREMENT', 'PLAN_ITEM', 'TEST'],
  PROOF_GAP: ['REQUIREMENT', 'PLAN_ITEM', 'PROOF'],
  PRESERVATION_RISK: ['IMPACT', 'CANDIDATE', 'PLAN_ITEM'],
  UI_ASSERTION_GAP: ['REQUIREMENT', 'CRITERION', 'ASSERTION'],
  PRODUCT_AMBIGUITY: ['SOURCE_UNIT', 'REQUIREMENT'],
  TECHNICAL_RISK: ['IMPACT', 'CANDIDATE', 'PLAN_ITEM'],
  SUGGESTION: TARGET_TYPES,
});

const REENTRY_BY_CATEGORY = Object.freeze({
  MISSING_REQUIREMENT: 'REQUIREMENTS',
  SOURCE_CONTRADICTION: 'REQUIREMENTS',
  IMPACT_INCOMPLETE: 'IMPACT',
  WRONG_TARGET: 'IMPACT',
  PLAN_GAP: 'PLAN',
  TEST_GAP: 'PLAN',
  PROOF_GAP: 'PLAN',
  PRESERVATION_RISK: 'PLAN',
  UI_ASSERTION_GAP: 'PLAN',
  PRODUCT_AMBIGUITY: 'USER_DECISION',
  TECHNICAL_RISK: 'PLAN',
  SUGGESTION: 'NONE',
});

function isBlockingCategory(category) {
  return category !== 'SUGGESTION';
}

function collectTargets({
  requirementRegistry,
  impactGraph,
  candidateManifest,
  planContract,
  uiAtomicityContract,
}) {
  const catalog = {
    SOURCE_UNIT: [],
    REQUIREMENT: [],
    IMPACT: [],
    CANDIDATE: [],
    PLAN_ITEM: [],
    TEST: [],
    PROOF: [],
    CRITERION: [],
    ASSERTION: [],
    PLAN_CONTRACT: [planContract.contract_hash],
  };

  for (const row of requirementRegistry.coverage || []) catalog.SOURCE_UNIT.push(row.unit_id);
  for (const row of requirementRegistry.requirements || []) catalog.REQUIREMENT.push(row.requirement_id);
  for (const row of impactGraph.impacts || []) catalog.IMPACT.push(row.impact_id);
  for (const row of candidateManifest.candidates || []) catalog.CANDIDATE.push(row.candidate_id);
  for (const item of planContract.plan_items || []) {
    catalog.PLAN_ITEM.push(item.plan_item_id);
    for (const test of item.test_obligations || []) catalog.TEST.push(test.test_id);
    for (const proof of item.proof_obligations || []) catalog.PROOF.push(proof.proof_id);
  }
  if (uiAtomicityContract) {
    for (const criterion of uiAtomicityContract.criteria || []) {
      catalog.CRITERION.push(criterion.criterion_id);
      for (const assertion of criterion.assertions || []) {
        catalog.ASSERTION.push(assertion.assertion_id);
      }
    }
  }

  for (const key of Object.keys(catalog)) {
    catalog[key] = [...new Set(catalog[key])].sort();
  }
  return catalog;
}

function validateCatalog(catalog) {
  V.assertExactKeys(
    catalog,
    TARGET_TYPES,
    [],
    'VNEXT_REVIEW_TARGET_CATALOG_KEYS_INVALID',
  );
  const all = new Set();
  for (const type of TARGET_TYPES) {
    if (!Array.isArray(catalog[type])) V.fail('VNEXT_REVIEW_TARGET_CATALOG_INVALID', type);
    for (const id of catalog[type]) {
      V.assertNonEmptyString(id, 'VNEXT_REVIEW_TARGET_ID_INVALID', type);
      if (all.has(id)) V.fail('VNEXT_REVIEW_TARGET_ID_COLLISION', id);
      all.add(id);
    }
  }
  return all;
}

function buildReviewContext({
  planningEnvelope,
  requirementRegistry,
  impactGraph,
  candidateManifest,
  planContract,
  directImportScan = null,
  uiAtomicityContract = null,
}) {
  PlanningEnvelope.validate(planningEnvelope);
  RequirementRegistry.validate(requirementRegistry, planningEnvelope.source_manifest);
  if (requirementRegistry.planning_envelope_hash !== planningEnvelope.contract_hash) {
    V.fail('VNEXT_REVIEW_ENVELOPE_BINDING_MISMATCH');
  }

  Impact.validateCandidateManifest(candidateManifest);
  if (impactGraph.candidate_manifest_hash !== candidateManifest.contract_hash) {
    V.fail('VNEXT_REVIEW_CANDIDATE_BINDING_MISMATCH');
  }
  Impact.validateImpactGraph(impactGraph, {
    requirementRegistry,
    candidateManifest,
    directImportScan,
  });
  Plan.validatePlanContract(planContract, {
    requirementRegistry,
    impactGraph,
    candidateManifest,
  });

  const uiChanges = Ui.uiChangeItems(requirementRegistry, planContract, candidateManifest)
    .map((row) => row.candidate_id)
    .sort();
  const uiApplicable = uiChanges.length > 0;

  if (uiApplicable && !uiAtomicityContract) {
    V.fail('VNEXT_REVIEW_UI_CONTRACT_REQUIRED');
  }
  if (uiAtomicityContract) {
    Ui.validateUiAtomicityContract(uiAtomicityContract, {
      requirementRegistry,
      impactGraph,
      candidateManifest,
      planContract,
    });
    if (Boolean(uiAtomicityContract.ui_applicable) !== uiApplicable) {
      V.fail('VNEXT_REVIEW_UI_APPLICABILITY_MISMATCH');
    }
  }

  const checks = [
    ['PLANNING_ENVELOPE', planningEnvelope.contract_hash],
    ['REQUIREMENT_REGISTRY', requirementRegistry.contract_hash],
    ['CANDIDATE_MANIFEST', candidateManifest.contract_hash],
    ['IMPACT_GRAPH', impactGraph.contract_hash],
    ['PLAN_CONTRACT', planContract.contract_hash],
  ];
  if (directImportScan) checks.push(['DIRECT_IMPORT_SCAN', directImportScan.contract_hash]);
  if (uiAtomicityContract) checks.push(['UI_ATOMICITY', uiAtomicityContract.contract_hash]);

  const mechanicalChecks = checks.map(([checkId, evidenceHash]) => Object.freeze({
    check_id: checkId,
    status: 'PASS',
    evidence_hash: evidenceHash,
  }));

  const targetCatalog = collectTargets({
    requirementRegistry,
    impactGraph,
    candidateManifest,
    planContract,
    uiAtomicityContract,
  });
  validateCatalog(targetCatalog);

  return V.sealContract({
    schema_version: CONTEXT_SCHEMA,
    planning_mode: planningEnvelope.planning_mode,
    planning_envelope_hash: planningEnvelope.contract_hash,
    requirement_registry_hash: requirementRegistry.contract_hash,
    candidate_manifest_hash: candidateManifest.contract_hash,
    impact_graph_hash: impactGraph.contract_hash,
    direct_import_scan_hash: directImportScan ? directImportScan.contract_hash : null,
    plan_contract_hash: planContract.contract_hash,
    ui_atomicity_hash: uiAtomicityContract ? uiAtomicityContract.contract_hash : null,
    ui_applicable: uiApplicable,
    mechanical_checks: mechanicalChecks,
    target_catalog: targetCatalog,
  });
}

function validateReviewContext(context) {
  V.assertExactKeys(
    context,
    [
      'schema_version',
      'planning_mode',
      'planning_envelope_hash',
      'requirement_registry_hash',
      'candidate_manifest_hash',
      'impact_graph_hash',
      'direct_import_scan_hash',
      'plan_contract_hash',
      'ui_atomicity_hash',
      'ui_applicable',
      'mechanical_checks',
      'target_catalog',
      'contract_hash',
    ],
    [],
    'VNEXT_REVIEW_CONTEXT_KEYS_INVALID',
  );
  if (context.schema_version !== CONTEXT_SCHEMA) V.fail('VNEXT_REVIEW_CONTEXT_SCHEMA_INVALID');
  if (!['INITIAL', 'REVISION'].includes(context.planning_mode)) {
    V.fail('VNEXT_REVIEW_CONTEXT_MODE_INVALID', context.planning_mode);
  }
  V.verifyContractHash(context, 'VNEXT_REVIEW_CONTEXT_HASH_MISMATCH');
  if (!Array.isArray(context.mechanical_checks) || context.mechanical_checks.length === 0) {
    V.fail('VNEXT_REVIEW_MECHANICAL_CHECKS_MISSING');
  }
  for (const check of context.mechanical_checks) {
    V.assertExactKeys(
      check,
      ['check_id', 'status', 'evidence_hash'],
      [],
      'VNEXT_REVIEW_MECHANICAL_CHECK_KEYS_INVALID',
    );
    if (check.status !== 'PASS') V.fail('VNEXT_REVIEW_MECHANICAL_CHECK_NOT_PASS', check.check_id);
    V.assertSha64(check.evidence_hash, 'VNEXT_REVIEW_MECHANICAL_EVIDENCE_INVALID', check.check_id);
  }
  validateCatalog(context.target_catalog);
  return true;
}

function verifyReviewContext(context, artifacts) {
  validateReviewContext(context);
  const rebuilt = buildReviewContext(artifacts);
  if (V.canonicalStringify(context) !== V.canonicalStringify(rebuilt)) {
    V.fail('VNEXT_REVIEW_CONTEXT_REBUILD_MISMATCH');
  }
  return true;
}

function reviewerOutputSchema(reviewContext) {
  validateReviewContext(reviewContext);
  const allTargetIds = TARGET_TYPES.flatMap((type) => reviewContext.target_catalog[type]);

  return {
    type: 'object',
    additionalProperties: false,
    required: ['findings'],
    properties: {
      findings: {
        type: 'array',
        items: {
          type: 'object',
          additionalProperties: false,
          required: [
            'category',
            'target_type',
            'target_id',
            'finding',
            'evidence',
            'required_correction',
            'dependency_target_ids',
          ],
          properties: {
            category: { type: 'string', enum: [...FINDING_CATEGORIES] },
            target_type: { type: 'string', enum: [...TARGET_TYPES] },
            target_id: { type: 'string', enum: allTargetIds },
            finding: { type: 'string', minLength: 1 },
            evidence: {
              type: 'array',
              minItems: 1,
              items: { type: 'string', minLength: 1 },
            },
            required_correction: { type: 'string', minLength: 1 },
            dependency_target_ids: {
              type: 'array',
              items: { type: 'string', enum: allTargetIds },
            },
          },
        },
      },
    },
  };
}

function normalizeFinding(row, index, reviewContext, allTargets) {
  V.assertExactKeys(
    row,
    [
      'category',
      'target_type',
      'target_id',
      'finding',
      'evidence',
      'required_correction',
      'dependency_target_ids',
    ],
    [],
    'VNEXT_REVIEW_FINDING_KEYS_INVALID',
  );

  if (!FINDING_CATEGORIES.includes(row.category)) {
    V.fail('VNEXT_REVIEW_FINDING_CATEGORY_INVALID', row.category);
  }
  if (!TARGET_TYPES.includes(row.target_type)) {
    V.fail('VNEXT_REVIEW_FINDING_TARGET_TYPE_INVALID', row.target_type);
  }
  if (!CATEGORY_TARGETS[row.category].includes(row.target_type)) {
    V.fail(
      'VNEXT_REVIEW_FINDING_TARGET_TYPE_INCOMPATIBLE',
      row.category + ':' + row.target_type,
    );
  }
  if (!reviewContext.target_catalog[row.target_type].includes(row.target_id)) {
    V.fail('VNEXT_REVIEW_FINDING_TARGET_UNKNOWN', row.target_id);
  }

  V.assertUnicodeExactText(
    row.finding,
    'VNEXT_REVIEW_FINDING_TEXT_INVALID',
    `findings[${index}].finding`,
  );
  V.assertUnicodeExactText(
    row.required_correction,
    'VNEXT_REVIEW_FINDING_CORRECTION_INVALID',
    `findings[${index}].required_correction`,
  );

  const evidence = V.uniqueStrings(
    row.evidence,
    'VNEXT_REVIEW_FINDING_EVIDENCE_INVALID',
    `findings[${index}].evidence`,
  ).sort();
  const dependencyTargetIds = V.uniqueStrings(
    row.dependency_target_ids,
    'VNEXT_REVIEW_FINDING_DEPENDENCIES_INVALID',
    `findings[${index}].dependency_target_ids`,
    { allowEmpty: true },
  ).sort();
  for (const id of dependencyTargetIds) {
    if (!allTargets.has(id)) V.fail('VNEXT_REVIEW_FINDING_DEPENDENCY_UNKNOWN', id);
    if (id === row.target_id) V.fail('VNEXT_REVIEW_FINDING_SELF_DEPENDENCY', id);
  }

  const blocking = isBlockingCategory(row.category);
  const reentryStage = REENTRY_BY_CATEGORY[row.category];
  const findingId = V.stableId('FND', [
    row.category,
    row.target_type,
    row.target_id,
    row.finding,
    evidence,
    row.required_correction,
    dependencyTargetIds,
  ]);

  return {
    finding_id: findingId,
    category: row.category,
    target_type: row.target_type,
    target_id: row.target_id,
    blocking,
    finding: row.finding,
    evidence,
    required_correction: row.required_correction,
    dependency_target_ids: dependencyTargetIds,
    reentry_stage: reentryStage,
  };
}

function buildReviewReport({ reviewContext, semanticReview }) {
  validateReviewContext(reviewContext);
  V.assertExactKeys(
    semanticReview,
    ['findings'],
    [],
    'VNEXT_REVIEW_OUTPUT_KEYS_INVALID',
  );
  if (!Array.isArray(semanticReview.findings)) {
    V.fail('VNEXT_REVIEW_FINDINGS_INVALID');
  }

  const allTargets = validateCatalog(reviewContext.target_catalog);
  const findings = semanticReview.findings
    .map((row, index) => normalizeFinding(row, index, reviewContext, allTargets))
    .sort((a, b) => a.finding_id.localeCompare(b.finding_id));

  const ids = findings.map((finding) => finding.finding_id);
  if (new Set(ids).size !== ids.length) V.fail('VNEXT_REVIEW_FINDING_DUPLICATE');

  let verdict = 'APPROVE';
  if (findings.some((finding) => finding.category === 'PRODUCT_AMBIGUITY')) {
    verdict = 'CLARIFICATION_REQUIRED';
  } else if (findings.some((finding) => finding.blocking)) {
    verdict = 'REVISE';
  }

  const blockingFindings = findings.filter((finding) => finding.blocking);
  const affectedTargetIds = [...new Set(blockingFindings.map((finding) => finding.target_id))].sort();
  const reentryStages = [...new Set(blockingFindings.map((finding) => finding.reentry_stage))].sort();

  return V.sealContract({
    schema_version: REPORT_SCHEMA,
    review_context_hash: reviewContext.contract_hash,
    planning_mode: reviewContext.planning_mode,
    plan_contract_hash: reviewContext.plan_contract_hash,
    ui_atomicity_hash: reviewContext.ui_atomicity_hash,
    finding_count: findings.length,
    blocking_finding_count: blockingFindings.length,
    verdict,
    affected_target_ids: affectedTargetIds,
    reentry_stages: reentryStages,
    findings,
  });
}

function validateReviewReport(report, reviewContext) {
  V.assertExactKeys(
    report,
    [
      'schema_version',
      'review_context_hash',
      'planning_mode',
      'plan_contract_hash',
      'ui_atomicity_hash',
      'finding_count',
      'blocking_finding_count',
      'verdict',
      'affected_target_ids',
      'reentry_stages',
      'findings',
      'contract_hash',
    ],
    [],
    'VNEXT_REVIEW_REPORT_KEYS_INVALID',
  );
  if (report.schema_version !== REPORT_SCHEMA) V.fail('VNEXT_REVIEW_REPORT_SCHEMA_INVALID');
  V.verifyContractHash(report, 'VNEXT_REVIEW_REPORT_HASH_MISMATCH');
  if (report.review_context_hash !== reviewContext.contract_hash) {
    V.fail('VNEXT_REVIEW_REPORT_CONTEXT_MISMATCH');
  }

  const semanticReview = {
    findings: report.findings.map((finding) => ({
      category: finding.category,
      target_type: finding.target_type,
      target_id: finding.target_id,
      finding: finding.finding,
      evidence: finding.evidence,
      required_correction: finding.required_correction,
      dependency_target_ids: finding.dependency_target_ids,
    })),
  };
  const rebuilt = buildReviewReport({ reviewContext, semanticReview });
  if (V.canonicalStringify(rebuilt) !== V.canonicalStringify(report)) {
    V.fail('VNEXT_REVIEW_REPORT_REBUILD_MISMATCH');
  }
  return true;
}

function buildReviewerPacket({ root, revision, reviewContext }) {
  validateReviewContext(reviewContext);
  return require('./vnext-producer-packet').buildProducerPacket({
    root,
    revision,
    entries: ['scripts/kodjo/lib/review-contract.js'],
    outputSchema: reviewerOutputSchema(reviewContext),
    inputs: { review_context: reviewContext },
  });
}

module.exports = {
  buildReviewerPacket,
  CONTEXT_SCHEMA,
  REPORT_SCHEMA,
  FINDING_CATEGORIES,
  TARGET_TYPES,
  CATEGORY_TARGETS,
  REENTRY_BY_CATEGORY,
  buildReviewContext,
  validateReviewContext,
  verifyReviewContext,
  reviewerOutputSchema,
  buildReviewReport,
  validateReviewReport,
};

'use strict';

/**
 * Refuse un chemin candidat ambigu au lieu de le normaliser puis de l'admettre.
 * Les chemins produits par Git sont relatifs, séparés par `/` et sans segments
 * vides, `.` ou `..`.
 */
function normalizeScopeCandidate(file) {
  if (typeof file !== 'string' || file.length === 0 || file.includes('\0')) return null;
  if (file.includes('\\') || file.startsWith('/') || /^[A-Za-z]:/.test(file)) return null;
  const parts = file.split('/');
  if (parts.some((part) => part === '' || part === '.' || part === '..')) return null;
  return parts.join('/');
}

/** Les règles sont validées séparément des chemins candidats. */
function normalizeScopeRule(raw) {
  if (typeof raw !== 'string' || raw.length === 0 || raw.includes('\0')) return null;
  const normalized = raw.replace(/\\/g, '/');
  const suffix = normalized.endsWith('/**') ? '/**' : normalized.endsWith('/*') ? '/*' : '';
  const base = suffix ? normalized.slice(0, -suffix.length) : normalized;
  if (!base || base.startsWith('/') || /^[A-Za-z]:/.test(base)) return null;
  const parts = base.split('/');
  if (parts.some((part) => part === '' || part === '.' || part === '..')) return null;
  return parts.join('/') + suffix;
}

function inScope(file, scopes) {
  const candidate = normalizeScopeCandidate(file);
  if (!candidate || !Array.isArray(scopes)) return false;
  return scopes.some((raw) => {
    const rule = normalizeScopeRule(raw);
    if (!rule) return false;
    if (rule.endsWith('/**')) return candidate === rule.slice(0, -3) || candidate.startsWith(rule.slice(0, -2));
    if (rule.endsWith('/*')) return candidate.startsWith(rule.slice(0, -1)) && !candidate.slice(rule.length - 1).includes('/');
    return candidate === rule;
  });
}

module.exports = { normalizeScopeCandidate, normalizeScopeRule, inScope };

'use strict';

const V = require('./vnext-contract');

const SCHEMA = 'kodjo.vnext.source-manifest.v1';
const SOURCE_KINDS = Object.freeze([
  'MARKDOWN', 'FIGMA', 'DECISION_REGISTER', 'DECISION_RECORD',
  'GITHUB_COMMENT', 'STRUCTURED_CONTRACT', 'CODE', 'OTHER',
]);
const AUTHORITIES = Object.freeze([
  'FUNCTIONAL', 'TECHNICAL', 'VISUAL', 'DECISION', 'OPERATIONAL', 'CODE',
]);
const UNIT_DISPOSITIONS = Object.freeze([
  'REQUIREMENT_SOURCE', 'CONTEXT_ONLY', 'SUPERSEDED', 'OUT_OF_SCOPE', 'AMBIGUOUS',
]);

function validateUnitInput(unit, sourceId) {
  V.assertExactKeys(unit, ['locator', 'fingerprint', 'disposition'], [], 'VNEXT_SOURCE_UNIT_KEYS_INVALID');
  V.assertUnicodeExactText(unit.locator, 'VNEXT_SOURCE_UNIT_LOCATOR_INVALID', 'unit.locator');
  V.assertSha64(unit.fingerprint, 'VNEXT_SOURCE_UNIT_FINGERPRINT_INVALID', 'unit.fingerprint');
  if (!UNIT_DISPOSITIONS.includes(unit.disposition)) V.fail('VNEXT_SOURCE_UNIT_DISPOSITION_INVALID', unit.disposition);
  return Object.freeze({
    unit_id: V.stableId('UNIT', [sourceId, unit.locator, unit.fingerprint]),
    locator: unit.locator,
    fingerprint: unit.fingerprint,
    disposition: unit.disposition,
  });
}

function validateSourceInput(source) {
  V.assertExactKeys(
    source,
    ['source_kind', 'authority', 'locator', 'revision', 'fingerprint', 'units'],
    [],
    'VNEXT_SOURCE_KEYS_INVALID',
  );
  if (!SOURCE_KINDS.includes(source.source_kind)) V.fail('VNEXT_SOURCE_KIND_INVALID', source.source_kind);
  if (!AUTHORITIES.includes(source.authority)) V.fail('VNEXT_SOURCE_AUTHORITY_INVALID', source.authority);
  V.assertUnicodeExactText(source.locator, 'VNEXT_SOURCE_LOCATOR_INVALID', 'source.locator');
  V.assertUnicodeExactText(source.revision, 'VNEXT_SOURCE_REVISION_INVALID', 'source.revision');
  V.assertSha64(source.fingerprint, 'VNEXT_SOURCE_FINGERPRINT_INVALID', 'source.fingerprint');
  if (!Array.isArray(source.units)) V.fail('VNEXT_SOURCE_UNITS_INVALID', 'units must be an array');

  const sourceId = V.stableId('SRC', [
    source.source_kind,
    source.authority,
    source.locator,
    source.revision,
    source.fingerprint,
  ]);
  const units = source.units.map((unit) => validateUnitInput(unit, sourceId));
  const unitIds = units.map((unit) => unit.unit_id);
  if (new Set(unitIds).size !== unitIds.length) V.fail('VNEXT_SOURCE_UNIT_DUPLICATE', sourceId);

  return Object.freeze({
    source_id: sourceId,
    source_kind: source.source_kind,
    authority: source.authority,
    locator: source.locator,
    revision: source.revision,
    fingerprint: source.fingerprint,
    units,
  });
}

function build(input) {
  V.assertExactKeys(input, ['slice_id', 'product_head', 'sources'], [], 'VNEXT_SOURCE_MANIFEST_INPUT_INVALID');
  V.assertSliceId(input.slice_id);
  V.assertSha40(input.product_head, 'VNEXT_SOURCE_PRODUCT_HEAD_INVALID', 'product_head');
  if (!Array.isArray(input.sources) || input.sources.length === 0) V.fail('VNEXT_SOURCE_LIST_EMPTY');
  const sources = input.sources.map(validateSourceInput);
  const ids = sources.map((source) => source.source_id);
  if (new Set(ids).size !== ids.length) V.fail('VNEXT_SOURCE_DUPLICATE');
  const locators = sources.map((source) => `${source.source_kind}\u0000${source.locator}\u0000${source.revision}`);
  if (new Set(locators).size !== locators.length) V.fail('VNEXT_SOURCE_LOCATOR_DUPLICATE');
  return V.sealContract({ schema_version: SCHEMA, slice_id: input.slice_id, product_head: input.product_head, sources });
}

function validate(manifest) {
  V.assertExactKeys(
    manifest,
    ['schema_version', 'slice_id', 'product_head', 'sources', 'contract_hash'],
    [],
    'VNEXT_SOURCE_MANIFEST_KEYS_INVALID',
  );
  if (manifest.schema_version !== SCHEMA) V.fail('VNEXT_SOURCE_MANIFEST_SCHEMA_INVALID', manifest.schema_version);
  V.verifyContractHash(manifest, 'VNEXT_SOURCE_MANIFEST_HASH_MISMATCH');
  const rebuilt = build({
    slice_id: manifest.slice_id,
    product_head: manifest.product_head,
    sources: manifest.sources.map((source) => ({
      source_kind: source.source_kind,
      authority: source.authority,
      locator: source.locator,
      revision: source.revision,
      fingerprint: source.fingerprint,
      units: source.units.map((unit) => ({
        locator: unit.locator,
        fingerprint: unit.fingerprint,
        disposition: unit.disposition,
      })),
    })),
  });
  if (V.canonicalStringify(rebuilt) !== V.canonicalStringify(manifest)) V.fail('VNEXT_SOURCE_MANIFEST_REBUILD_MISMATCH');
  return true;
}

module.exports = { SCHEMA, SOURCE_KINDS, AUTHORITIES, UNIT_DISPOSITIONS, build, validate };

'use strict';

const V = require('./vnext-contract');
const RequirementRegistry = require('./requirement-registry');
const Impact = require('./impact-graph');
const Plan = require('./plan-contract');
// VNext owns this conservative path guard; source UI requirements remain primary.
function isUiPath(value) {
  return /^(?:app\/|src\/features\/|src\/shared\/ui\/|src\/shared\/i18n\/|assets\/icons\/)/.test(value)
    && !/(?:^|\/)(__tests__|tests?)\/|\.(?:test|spec)\.[^.]+$/.test(value);
}

const SCHEMA = 'kodjo.vnext.ui-criteria.v2';

const RISK_TYPES = Object.freeze(['FUNCTIONAL', 'VISUAL', 'ACCESSIBILITY', 'DEVICE']);
const COMPONENT_DECISIONS = Object.freeze(['REUSE', 'EXTEND', 'CREATE']);
const ASSERTION_PROPERTY_TYPES = Object.freeze([
  'PRESENCE',
  'CONTENT',
  'STATE',
  'GEOMETRY',
  'RELATION',
  'STYLE',
  'LAYERING',
  'INTERACTION',
  'RESPONSIVE',
]);
const VISUAL_PROPERTIES = new Set(['GEOMETRY', 'RELATION', 'STYLE', 'LAYERING', 'RESPONSIVE']);
const STRUCTURAL_PROPERTIES = new Set(['PRESENCE', 'CONTENT', 'STATE']);
const PROOF_TYPES = new Set([
  'FUNCTIONAL_TEST',
  'STATIC_ANALYSIS',
  'VISUAL_COMPARE',
  'ACCESSIBILITY_CHECK',
  'DEVICE_CHECK',
]);

function unique(values, code, label, { allowEmpty = false } = {}) {
  return V.uniqueStrings(values, code, label, { allowEmpty }).sort();
}

function sameSet(left, right) {
  return V.canonicalStringify([...new Set(left)].sort())
    === V.canonicalStringify([...new Set(right)].sort());
}

function requirementIndex(requirementRegistry) {
  RequirementRegistry.assertReady(requirementRegistry);
  return new Map(requirementRegistry.requirements.map((requirement) => [
    requirement.requirement_id,
    requirement,
  ]));
}

// Source-first UI requirements cover effects outside the historical UI roots.
// Keep the path guard as an additional conservative check, never as an exemption.
function uiChangeItems(requirementRegistry, planContract, candidateManifest) {
  const requirements = requirementIndex(requirementRegistry);
  const candidates = new Map(candidateManifest.candidates.map(row => [row.candidate_id, row]));
  return planContract.plan_items.flatMap(item => item.change_items.filter(change =>
    candidates.get(change.candidate_id)?.candidate_kind !== 'TEST'
    && (requirements.get(item.requirement_id)?.kind === 'UI' || isUiPath(change.path))));
}

function planIndex(planContract) {
  const byRequirement = new Map();
  for (const item of planContract.plan_items || []) {
    if (byRequirement.has(item.requirement_id)) {
      V.fail('VNEXT_UI_PLAN_ITEM_DUPLICATE', item.requirement_id);
    }
    byRequirement.set(item.requirement_id, item);
  }
  return byRequirement;
}

function candidateIndex(candidateManifest) {
  Impact.validateCandidateManifest(candidateManifest);
  return new Map(candidateManifest.candidates.map((candidate) => [
    candidate.candidate_id,
    candidate,
  ]));
}

function impactIndex(impactGraph) {
  const byId = new Map();
  for (const impact of impactGraph.impacts || []) {
    if (byId.has(impact.impact_id)) V.fail('VNEXT_UI_IMPACT_ID_DUPLICATE', impact.impact_id);
    byId.set(impact.impact_id, impact);
  }
  return byId;
}

function proofIndex(planItem) {
  const byId = new Map();
  for (const proof of planItem.proof_obligations || []) {
    if (byId.has(proof.proof_id)) V.fail('VNEXT_UI_PLAN_PROOF_ID_DUPLICATE', proof.proof_id);
    byId.set(proof.proof_id, proof);
  }
  return byId;
}

function sourceSnapshot(requirement) {
  return Object.freeze({
    source_id: requirement.source_id,
    unit_id: requirement.unit_id,
    source_kind: requirement.source.source_kind,
    authority: requirement.source.authority,
    locator: requirement.source.locator,
    revision: requirement.source.revision,
    unit_locator: requirement.source.unit_locator,
    unit_fingerprint: requirement.source.unit_fingerprint,
  });
}

function validateRiskProofs(riskTypes, proofTypes, label) {
  if (riskTypes.includes('VISUAL') && !proofTypes.includes('VISUAL_COMPARE')) {
    V.fail('VNEXT_UI_RISK_PROOF_INVALID', label + ': VISUAL exige VISUAL_COMPARE');
  }
  if (riskTypes.includes('ACCESSIBILITY') && !proofTypes.includes('ACCESSIBILITY_CHECK')) {
    V.fail('VNEXT_UI_RISK_PROOF_INVALID', label + ': ACCESSIBILITY exige ACCESSIBILITY_CHECK');
  }
  if (riskTypes.includes('DEVICE') && !proofTypes.includes('DEVICE_CHECK')) {
    V.fail('VNEXT_UI_RISK_PROOF_INVALID', label + ': DEVICE exige DEVICE_CHECK');
  }
  if (riskTypes.includes('FUNCTIONAL')
      && !proofTypes.some((proof) => proof === 'FUNCTIONAL_TEST' || proof === 'STATIC_ANALYSIS')) {
    V.fail('VNEXT_UI_RISK_PROOF_INVALID', label + ': FUNCTIONAL exige FUNCTIONAL_TEST ou STATIC_ANALYSIS');
  }
}

function validateAssertionProofs(propertyType, proofTypes, requirement, label) {
  if (VISUAL_PROPERTIES.has(propertyType)) {
    if (!proofTypes.includes('VISUAL_COMPARE')) {
      V.fail('VNEXT_UI_ASSERTION_PROOF_INVALID', label + ': ' + propertyType + ' exige VISUAL_COMPARE');
    }
    if (!['VISUAL', 'DECISION'].includes(requirement.source.authority)) {
      V.fail(
        'VNEXT_UI_ASSERTION_VISUAL_SOURCE_INVALID',
        label + ': propriété visuelle sans source VISUAL/DECISION',
      );
    }
  }

  if (propertyType === 'INTERACTION') {
    if (!proofTypes.some((proof) => proof === 'FUNCTIONAL_TEST' || proof === 'STATIC_ANALYSIS')) {
      V.fail(
        'VNEXT_UI_ASSERTION_PROOF_INVALID',
        label + ': INTERACTION exige FUNCTIONAL_TEST ou STATIC_ANALYSIS',
      );
    }
    if (!['FUNCTIONAL', 'DECISION'].includes(requirement.source.authority)) {
      V.fail(
        'VNEXT_UI_ASSERTION_INTERACTION_SOURCE_INVALID',
        label + ': interaction sans source FUNCTIONAL/DECISION',
      );
    }
  }

  if (STRUCTURAL_PROPERTIES.has(propertyType)
      && !proofTypes.some((proof) =>
        ['FUNCTIONAL_TEST', 'STATIC_ANALYSIS', 'VISUAL_COMPARE'].includes(proof))) {
    V.fail(
      'VNEXT_UI_ASSERTION_PROOF_INVALID',
      label + ': ' + propertyType + ' exige une preuve observable',
    );
  }
}

function normalizeReuse(input, candidateById, label) {
  const searchIds = unique(
    input.reuse_search_candidate_ids,
    'VNEXT_UI_REUSE_SEARCH_INVALID',
    label + '.reuse_search_candidate_ids',
  );
  for (const candidateId of searchIds) {
    const candidate = candidateById.get(candidateId);
    if (!candidate) V.fail('VNEXT_UI_REUSE_CANDIDATE_UNKNOWN', candidateId);
    if (candidate.origin !== 'GIT_TREE') V.fail('VNEXT_UI_REUSE_CANDIDATE_NOT_EXISTING', candidateId);
    if (!isUiPath(candidate.path) && !['CODE', 'ASSET', 'CREATE_SLOT'].includes(candidate.candidate_kind)) V.fail('VNEXT_UI_REUSE_CANDIDATE_NOT_UI', candidate.path);
  }

  if (!COMPONENT_DECISIONS.includes(input.component_decision)) {
    V.fail('VNEXT_UI_COMPONENT_DECISION_INVALID', input.component_decision);
  }
  V.assertUnicodeExactText(
    input.selected_component,
    'VNEXT_UI_SELECTED_COMPONENT_INVALID',
    label + '.selected_component',
  );
  V.assertUnicodeExactText(
    input.decision_justification,
    'VNEXT_UI_COMPONENT_JUSTIFICATION_INVALID',
    label + '.decision_justification',
  );

  if (['REUSE', 'EXTEND'].includes(input.component_decision)) {
    V.assertNonEmptyString(
      input.selected_component_candidate_id,
      'VNEXT_UI_SELECTED_COMPONENT_CANDIDATE_REQUIRED',
      label + '.selected_component_candidate_id',
    );
    if (!searchIds.includes(input.selected_component_candidate_id)) {
      V.fail(
        'VNEXT_UI_SELECTED_COMPONENT_NOT_SEARCHED',
        input.selected_component_candidate_id,
      );
    }
  } else if (input.selected_component_candidate_id !== null) {
    V.fail('VNEXT_UI_CREATE_EXISTING_COMPONENT_FORBIDDEN', String(input.selected_component_candidate_id));
  }

  return {
    reuse_search_candidate_ids: searchIds,
    component_decision: input.component_decision,
    selected_component: input.selected_component,
    selected_component_candidate_id: input.selected_component_candidate_id,
    decision_justification: input.decision_justification,
  };
}

function normalizeAssertions({
  assertions,
  criterionId,
  criterionProofIds,
  criterionChangeImpactIds,
  proofById,
  impactById,
  requirement,
}) {
  if (!Array.isArray(assertions) || assertions.length === 0) {
    V.fail('VNEXT_UI_ASSERTIONS_MISSING', criterionId);
  }

  const seen = new Set();
  const normalized = assertions.map((assertion, index) => {
    V.assertExactKeys(
      assertion,
      [
        'subject', 'property_type', 'expected',
        'proof_ids', 'covered_change_impact_ids',
      ],
      [],
      'VNEXT_UI_ASSERTION_KEYS_INVALID',
    );

    V.assertUnicodeExactText(
      assertion.subject,
      'VNEXT_UI_ASSERTION_SUBJECT_INVALID',
      `assertions[${index}].subject`,
    );
    if (!ASSERTION_PROPERTY_TYPES.includes(assertion.property_type)) {
      V.fail('VNEXT_UI_ASSERTION_PROPERTY_INVALID', assertion.property_type);
    }
    V.assertUnicodeExactText(
      assertion.expected,
      'VNEXT_UI_ASSERTION_EXPECTED_INVALID',
      `assertions[${index}].expected`,
    );

    const proofIds = unique(
      assertion.proof_ids,
      'VNEXT_UI_ASSERTION_PROOFS_INVALID',
      `assertions[${index}].proof_ids`,
    );
    for (const proofId of proofIds) {
      if (!criterionProofIds.includes(proofId)) {
        V.fail('VNEXT_UI_ASSERTION_PROOF_OUTSIDE_CRITERION', proofId);
      }
      if (!proofById.has(proofId)) V.fail('VNEXT_UI_ASSERTION_PROOF_UNKNOWN', proofId);
    }
    const proofTypes = proofIds.map((proofId) => proofById.get(proofId).proof_type);
    validateAssertionProofs(
      assertion.property_type,
      proofTypes,
      requirement,
      `assertions[${index}]`,
    );

    const coveredChangeImpactIds = unique(
      assertion.covered_change_impact_ids,
      'VNEXT_UI_ASSERTION_CHANGE_COVERAGE_INVALID',
      `assertions[${index}].covered_change_impact_ids`,
    );
    for (const impactId of coveredChangeImpactIds) {
      if (!criterionChangeImpactIds.includes(impactId)) {
        V.fail('VNEXT_UI_ASSERTION_IMPACT_OUTSIDE_CRITERION', impactId);
      }
      if (!impactById.has(impactId)) V.fail('VNEXT_UI_ASSERTION_IMPACT_UNKNOWN', impactId);
    }

    const assertionId = V.stableId('AST', [
      criterionId,
      assertion.subject,
      assertion.property_type,
      assertion.expected,
      proofIds,
      coveredChangeImpactIds,
    ]);
    if (seen.has(assertionId)) V.fail('VNEXT_UI_ASSERTION_DUPLICATE', assertionId);
    seen.add(assertionId);

    return {
      assertion_id: assertionId,
      subject: assertion.subject,
      source: sourceSnapshot(requirement),
      property_type: assertion.property_type,
      expected: assertion.expected,
      proof_ids: proofIds,
      proof_required: [...new Set(proofTypes)].sort(),
      covered_change_impact_ids: coveredChangeImpactIds,
    };
  }).sort((a, b) => a.assertion_id.localeCompare(b.assertion_id));

  const allocatedProofIds = normalized.flatMap((assertion) => assertion.proof_ids);
  if (!sameSet(allocatedProofIds, criterionProofIds)) {
    V.fail(
      'VNEXT_UI_ASSERTION_PROOF_COVERAGE_INCOMPLETE',
      criterionId + ': chaque preuve du critère doit être allouée',
    );
  }

  const coveredImpacts = normalized.flatMap((assertion) => assertion.covered_change_impact_ids);
  if (!sameSet(coveredImpacts, criterionChangeImpactIds)) {
    V.fail(
      'VNEXT_UI_ASSERTION_CHANGE_COVERAGE_INCOMPLETE',
      criterionId + ': chaque changement du critère doit être couvert',
    );
  }

  return normalized;
}

function buildUiAtomicityContract({
  requirementRegistry,
  impactGraph,
  candidateManifest,
  planContract,
  criteria,
}) {
  RequirementRegistry.assertReady(requirementRegistry);
  Impact.validateCandidateManifest(candidateManifest);
  Plan.validatePlanContract(planContract, {
    requirementRegistry,
    impactGraph,
    candidateManifest,
  });

  if (!Array.isArray(criteria)) V.fail('VNEXT_UI_CRITERIA_INVALID');

  const requirements = requirementIndex(requirementRegistry);
  const plans = planIndex(planContract);
  const candidates = candidateIndex(candidateManifest);
  const impacts = impactIndex(impactGraph);

  const uiChangeImpactIds = [];
  const uiChangeByRequirement = new Map();
  const uiChanges = new Set(uiChangeItems(requirementRegistry, planContract, candidateManifest).map(row => row.impact_id));

  for (const planItem of planContract.plan_items) {
    for (const change of planItem.change_items) {
      if (!uiChanges.has(change.impact_id)) continue;
      uiChangeImpactIds.push(change.impact_id);
      const list = uiChangeByRequirement.get(planItem.requirement_id) || [];
      list.push(change.impact_id);
      uiChangeByRequirement.set(planItem.requirement_id, list);
    }
  }

  const uiApplicable = uiChangeImpactIds.length > 0;
  if (!uiApplicable && criteria.length > 0) {
    V.fail('VNEXT_UI_CRITERIA_WITHOUT_UI_CHANGE');
  }

  const normalizedCriteria = [];
  const seenCriterionIds = new Set();

  for (let index = 0; index < criteria.length; index += 1) {
    const input = criteria[index];
    V.assertExactKeys(
      input,
      [
        'requirement_id',
        'statement',
        'risk_types',
        'reuse_search_candidate_ids',
        'component_decision',
        'selected_component',
        'selected_component_candidate_id',
        'decision_justification',
        'change_impact_ids',
        'proof_ids',
        'assertions',
      ],
      [],
      'VNEXT_UI_CRITERION_KEYS_INVALID',
    );

    const requirement = requirements.get(input.requirement_id);
    if (!requirement) V.fail('VNEXT_UI_REQUIREMENT_UNKNOWN', input.requirement_id);
    if (requirement.kind !== 'UI') {
      V.fail('VNEXT_UI_CRITERION_NON_UI_REQUIREMENT', input.requirement_id);
    }

    const planItem = plans.get(input.requirement_id);
    if (!planItem) V.fail('VNEXT_UI_PLAN_ITEM_MISSING', input.requirement_id);
    if (planItem.disposition !== 'CHANGE') {
      V.fail('VNEXT_UI_CRITERION_NO_CHANGE_FORBIDDEN', input.requirement_id);
    }

    V.assertUnicodeExactText(
      input.statement,
      'VNEXT_UI_CRITERION_STATEMENT_INVALID',
      `criteria[${index}].statement`,
    );

    const riskTypes = unique(
      input.risk_types,
      'VNEXT_UI_RISK_TYPES_INVALID',
      `criteria[${index}].risk_types`,
    );
    if (riskTypes.some((risk) => !RISK_TYPES.includes(risk))) {
      V.fail('VNEXT_UI_RISK_TYPES_INVALID', riskTypes.join(','));
    }

    const planProofs = proofIndex(planItem);
    const proofIds = unique(
      input.proof_ids,
      'VNEXT_UI_CRITERION_PROOFS_INVALID',
      `criteria[${index}].proof_ids`,
    );
    for (const proofId of proofIds) {
      if (!planProofs.has(proofId)) V.fail('VNEXT_UI_CRITERION_PROOF_UNKNOWN', proofId);
    }
    const proofTypes = proofIds.map((proofId) => planProofs.get(proofId).proof_type);
    validateRiskProofs(riskTypes, proofTypes, `criteria[${index}]`);

    const availableUiImpacts = new Set(uiChangeByRequirement.get(input.requirement_id) || []);
    const changeImpactIds = unique(
      input.change_impact_ids,
      'VNEXT_UI_CRITERION_IMPACTS_INVALID',
      `criteria[${index}].change_impact_ids`,
    );
    for (const impactId of changeImpactIds) {
      if (!availableUiImpacts.has(impactId)) {
        V.fail('VNEXT_UI_CRITERION_IMPACT_INVALID', impactId);
      }
    }

    const reuse = normalizeReuse(input, candidates, `criteria[${index}]`);

    const criterionId = V.stableId('CRT', [
      input.requirement_id,
      input.statement,
      changeImpactIds,
      proofIds,
    ]);
    if (seenCriterionIds.has(criterionId)) V.fail('VNEXT_UI_CRITERION_DUPLICATE', criterionId);
    seenCriterionIds.add(criterionId);

    const assertions = normalizeAssertions({
      assertions: input.assertions,
      criterionId,
      criterionProofIds: proofIds,
      criterionChangeImpactIds: changeImpactIds,
      proofById: planProofs,
      impactById: impacts,
      requirement,
    });

    normalizedCriteria.push({
      criterion_id: criterionId,
      requirement_id: input.requirement_id,
      source: sourceSnapshot(requirement),
      statement: input.statement,
      risk_types: riskTypes,
      ...reuse,
      change_impact_ids: changeImpactIds,
      proof_ids: proofIds,
      proof_required: [...new Set(proofTypes)].sort(),
      assertions,
    });
  }

  normalizedCriteria.sort((a, b) => a.criterion_id.localeCompare(b.criterion_id));

  const criteriaByRequirement = new Map();
  for (const criterion of normalizedCriteria) {
    const list = criteriaByRequirement.get(criterion.requirement_id) || [];
    list.push(criterion);
    criteriaByRequirement.set(criterion.requirement_id, list);
  }

  for (const [requirementId, impactIds] of uiChangeByRequirement) {
    const requirement = requirements.get(requirementId);
    if (!requirement || requirement.kind !== 'UI') {
      V.fail('VNEXT_UI_REQUIREMENT_MISSING_FOR_UI_CHANGE', requirementId);
    }
    const requirementCriteria = criteriaByRequirement.get(requirementId) || [];
    if (requirementCriteria.length === 0) {
      V.fail('VNEXT_UI_CRITERION_MISSING', requirementId);
    }
    const covered = requirementCriteria.flatMap((criterion) => criterion.change_impact_ids);
    if (!sameSet(covered, impactIds)) {
      V.fail('VNEXT_UI_CRITERION_CHANGE_COVERAGE_INCOMPLETE', requirementId);
    }
  }

  const assertionIds = normalizedCriteria.flatMap((criterion) =>
    criterion.assertions.map((assertion) => assertion.assertion_id));
  if (new Set(assertionIds).size !== assertionIds.length) {
    V.fail('VNEXT_UI_ASSERTION_GLOBAL_DUPLICATE');
  }

  return V.sealContract({
    schema_version: SCHEMA,
    requirement_registry_hash: requirementRegistry.contract_hash,
    impact_graph_hash: impactGraph.contract_hash,
    candidate_manifest_hash: candidateManifest.contract_hash,
    plan_contract_hash: planContract.contract_hash,
    ui_applicable: uiApplicable,
    ui_change_impact_ids: [...uiChangeImpactIds].sort(),
    criterion_count: normalizedCriteria.length,
    assertion_count: assertionIds.length,
    assertion_ids_sha256: V.canonicalHash([...assertionIds].sort()),
    criteria: normalizedCriteria,
  });
}

function validateUiAtomicityContract(contract, {
  requirementRegistry,
  impactGraph,
  candidateManifest,
  planContract,
}) {
  V.assertExactKeys(
    contract,
    [
      'schema_version',
      'requirement_registry_hash',
      'impact_graph_hash',
      'candidate_manifest_hash',
      'plan_contract_hash',
      'ui_applicable',
      'ui_change_impact_ids',
      'criterion_count',
      'assertion_count',
      'assertion_ids_sha256',
      'criteria',
      'contract_hash',
    ],
    [],
    'VNEXT_UI_CONTRACT_KEYS_INVALID',
  );
  if (contract.schema_version !== SCHEMA) V.fail('VNEXT_UI_CONTRACT_SCHEMA_INVALID');
  V.verifyContractHash(contract, 'VNEXT_UI_CONTRACT_HASH_MISMATCH');

  if (contract.requirement_registry_hash !== requirementRegistry.contract_hash) {
    V.fail('VNEXT_UI_REQUIREMENT_REGISTRY_HASH_MISMATCH');
  }
  if (contract.impact_graph_hash !== impactGraph.contract_hash) {
    V.fail('VNEXT_UI_IMPACT_GRAPH_HASH_MISMATCH');
  }
  if (contract.candidate_manifest_hash !== candidateManifest.contract_hash) {
    V.fail('VNEXT_UI_CANDIDATE_MANIFEST_HASH_MISMATCH');
  }
  if (contract.plan_contract_hash !== planContract.contract_hash) {
    V.fail('VNEXT_UI_PLAN_CONTRACT_HASH_MISMATCH');
  }

  const criteriaInput = contract.criteria.map((criterion) => ({
    requirement_id: criterion.requirement_id,
    statement: criterion.statement,
    risk_types: criterion.risk_types,
    reuse_search_candidate_ids: criterion.reuse_search_candidate_ids,
    component_decision: criterion.component_decision,
    selected_component: criterion.selected_component,
    selected_component_candidate_id: criterion.selected_component_candidate_id,
    decision_justification: criterion.decision_justification,
    change_impact_ids: criterion.change_impact_ids,
    proof_ids: criterion.proof_ids,
    assertions: criterion.assertions.map((assertion) => ({
      subject: assertion.subject,
      property_type: assertion.property_type,
      expected: assertion.expected,
      proof_ids: assertion.proof_ids,
      covered_change_impact_ids: assertion.covered_change_impact_ids,
    })),
  }));

  const rebuilt = buildUiAtomicityContract({
    requirementRegistry,
    impactGraph,
    candidateManifest,
    planContract,
    criteria: criteriaInput,
  });

  if (V.canonicalStringify(rebuilt) !== V.canonicalStringify(contract)) {
    V.fail('VNEXT_UI_CONTRACT_REBUILD_MISMATCH');
  }
  return true;
}

module.exports = {
  uiChangeItems,
  SCHEMA,
  RISK_TYPES,
  COMPONENT_DECISIONS,
  ASSERTION_PROPERTY_TYPES,
  buildUiAtomicityContract,
  validateUiAtomicityContract,
};

'use strict';

const crypto = require('node:crypto');

const SHA40 = /^[0-9a-f]{40}$/;
const SHA64 = /^[0-9a-f]{64}$/;
const SLICE_ID = /^[A-Za-z0-9._-]{1,80}$/;
const STABLE_ID_PREFIX = /^[A-Z][A-Z0-9_]{1,15}$/;

function fail(code, detail) {
  const error = new Error(detail ? `${code}: ${detail}` : code);
  error.code = code;
  throw error;
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function canonicalize(value, path = '$') {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') return value;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) fail('VNEXT_CANONICAL_NUMBER_INVALID', path);
    return value;
  }
  if (Array.isArray(value)) return value.map((item, index) => canonicalize(item, `${path}[${index}]`));
  if (!isPlainObject(value)) fail('VNEXT_CANONICAL_TYPE_INVALID', path);

  const output = {};
  for (const key of Object.keys(value).sort()) {
    if (value[key] === undefined) fail('VNEXT_CANONICAL_UNDEFINED', `${path}.${key}`);
    output[key] = canonicalize(value[key], `${path}.${key}`);
  }
  return output;
}

function canonicalStringify(value) {
  return JSON.stringify(canonicalize(value));
}

function sha256(value) {
  return crypto.createHash('sha256').update(String(value), 'utf8').digest('hex');
}

function canonicalHash(value) {
  return sha256(canonicalStringify(value));
}

function stableId(prefix, parts) {
  if (!STABLE_ID_PREFIX.test(String(prefix || ''))) fail('VNEXT_ID_PREFIX_INVALID', String(prefix));
  if (!Array.isArray(parts) || parts.length === 0) fail('VNEXT_ID_PARTS_INVALID');
  return `${prefix}-${canonicalHash(parts).slice(0, 24)}`;
}

function assertExactKeys(value, required, optional = [], code = 'VNEXT_CONTRACT_KEYS_INVALID') {
  if (!isPlainObject(value)) fail(code, 'object expected');
  const allowed = new Set([...required, ...optional]);
  const missing = required.filter((key) => !Object.prototype.hasOwnProperty.call(value, key));
  const extra = Object.keys(value).filter((key) => !allowed.has(key));
  if (missing.length || extra.length) {
    fail(code, `missing=[${missing.join(',')}] extra=[${extra.join(',')}]`);
  }
}

function assertNonEmptyString(value, code, label = 'value') {
  if (typeof value !== 'string' || value.length === 0) fail(code, `${label} must be non-empty text`);
  return value;
}

function assertUnicodeExactText(value, code = 'VNEXT_UNICODE_TEXT_INVALID', label = 'text') {
  assertNonEmptyString(value, code, label);
  if (value.includes('\uFFFD')) fail(code, `${label} contains replacement character U+FFFD`);
  if (/#U[0-9A-Fa-f]{4,6}/.test(value)) fail(code, `${label} contains #Uxxxx degradation`);
  if (/\\u[0-9A-Fa-f]{4}/.test(value)) fail(code, `${label} contains literal \\uXXXX degradation`);
  return value;
}

function assertSha40(value, code, label = 'sha') {
  if (!SHA40.test(String(value || ''))) fail(code, `${label} must be lowercase SHA-40`);
  return value;
}

function assertSha64(value, code, label = 'sha256') {
  if (!SHA64.test(String(value || ''))) fail(code, `${label} must be lowercase SHA-256`);
  return value;
}

function assertSliceId(value, code = 'VNEXT_SLICE_ID_INVALID') {
  if (!SLICE_ID.test(String(value || ''))) fail(code, 'slice_id invalid');
  return value;
}

function assertIsoDate(value, code = 'VNEXT_DATE_INVALID', label = 'date') {
  if (typeof value !== 'string' || Number.isNaN(Date.parse(value))) fail(code, `${label} must be ISO-8601 text`);
  return value;
}

function uniqueStrings(values, code, label, { allowEmpty = false } = {}) {
  if (!Array.isArray(values) || (!allowEmpty && values.length === 0)) fail(code, `${label} array invalid`);
  const out = values.map((value, index) => assertNonEmptyString(value, code, `${label}[${index}]`));
  if (new Set(out).size !== out.length) fail(code, `${label} contains duplicates`);
  return out;
}

function sealContract(value) {
  if (!isPlainObject(value)) fail('VNEXT_CONTRACT_INVALID', 'object expected');
  if (Object.prototype.hasOwnProperty.call(value, 'contract_hash')) fail('VNEXT_CONTRACT_ALREADY_SEALED');
  return Object.freeze({ ...value, contract_hash: canonicalHash(value) });
}

function verifyContractHash(value, code = 'VNEXT_CONTRACT_HASH_MISMATCH') {
  if (!isPlainObject(value)) fail(code, 'object expected');
  assertSha64(value.contract_hash, code, 'contract_hash');
  const unsigned = { ...value };
  delete unsigned.contract_hash;
  const actual = canonicalHash(unsigned);
  if (actual !== value.contract_hash) fail(code, `expected=${value.contract_hash} actual=${actual}`);
  return true;
}

module.exports = {
  SHA40,
  SHA64,
  SLICE_ID,
  fail,
  isPlainObject,
  canonicalize,
  canonicalStringify,
  sha256,
  canonicalHash,
  stableId,
  assertExactKeys,
  assertNonEmptyString,
  assertUnicodeExactText,
  assertSha40,
  assertSha64,
  assertSliceId,
  assertIsoDate,
  uniqueStrings,
  sealContract,
  verifyContractHash,
};

'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');
const V = require('./vnext-contract');

// Includes the full local CommonJS closure, not just a function's toString().
function buildProducerPacket({ root, revision = 'HEAD', entries, outputSchema, inputs }) {
  const base = fs.realpathSync(root);
  const git = args => execFileSync('git', args, { cwd: base, encoding: 'utf8', windowsHide: true, maxBuffer: 32 * 1024 * 1024 });
  let sourceRevision;
  let tracked;
  try {
    sourceRevision = git(['rev-parse', revision + '^{commit}']).trim();
    tracked = new Set(git(['ls-tree', '-r', '--name-only', '-z', sourceRevision]).split('\0').filter(Boolean));
  } catch (_) { V.fail('VNEXT_PRODUCER_SOURCE_NON_VERIFIABLE'); }
  const seen = new Map();
  function visit(relative) {
    if (relative.includes('\\') || path.posix.isAbsolute(relative) || relative.split('/').includes('..')) V.fail('VNEXT_PRODUCER_DEPENDENCY_OUTSIDE_ROOT', relative);
    const rel = path.posix.normalize(relative);
    if (!tracked.has(rel)) V.fail('VNEXT_PRODUCER_SOURCE_NON_VERIFIABLE', rel);
    if (seen.has(rel)) return;
    const source = git(['show', sourceRevision + ':' + rel]);
    const sourceHash = V.sha256(source);
    seen.set(rel, { path: rel, source_hash: sourceHash, source });
    // Dynamic requires/imports are not silently called a complete closure.
    if (/\brequire\s*\(\s*[^'"\s]/.test(source) || /\bimport\s*\(/.test(source)) {
      V.fail('VNEXT_PRODUCER_DYNAMIC_DEPENDENCY_NON_VERIFIABLE', rel);
    }
    if (/^\s*(?:import\s|export\s)/m.test(source)) V.fail('VNEXT_PRODUCER_ESM_DEPENDENCY_NON_VERIFIABLE', rel);
    for (const match of source.matchAll(/\brequire\s*\(\s*(['"])([^'"]+)\1\s*\)/g)) {
      if (match[2].startsWith('node:')) continue;
      if (!match[2].startsWith('.')) V.fail('VNEXT_PRODUCER_EXTERNAL_DEPENDENCY_NON_VERIFIABLE', match[2]);
      const dep = path.posix.normalize(path.posix.join(path.posix.dirname(rel), match[2]));
      const resolved = [dep, dep + '.js', dep + '.json', dep + '/index.js'].find(candidate => tracked.has(candidate));
      if (!resolved) V.fail('VNEXT_PRODUCER_SOURCE_NON_VERIFIABLE', dep);
      visit(resolved);
    }
  }
  for (const entry of V.uniqueStrings(entries, 'VNEXT_PRODUCER_ENTRIES_INVALID', 'entries')) visit(entry);
  return V.sealContract({
    schema_version: 'kodjo.vnext.producer-packet.v2',
    source_revision: sourceRevision,
    consumers: [...seen.values()].sort((a, b) => a.path.localeCompare(b.path)),
    output_schema: outputSchema,
    inputs,
    transport: 'JSON_UTF8',
  });
}

module.exports = { buildProducerPacket };
